INSERT INTO `law_mozambique` VALUES (1,'Preamble','Preamble','Preamble','Meeting the age-old desires of our people, the armed struggle for national liberation, whose purpose was to liberate the land and Man, brought together all the patriotic sectors of Mozambican society in the same ideals of freedom, unity, justice and progress.\nWhen national independence was won on the 25th of June 1975, the Mozambican people were given back their fundamental rights and freedoms.\nThe Constitution of 1990 introduced the democratic rule of law, based on the separation and interdependence of powers and on pluralism. It laid down the structural parameters for modernisation, making a decisive contribution to the beginning of a democratic climate that led the country to its first multiparty elections.\nThis Constitution reaffirms, develops and deepens the fundamental principles of the Mozambican State, and enshrines the sovereign nature of the democratic rule of law, based on pluralism of expression and partisan organisation and on respect for and the guarantee of fundamental rights and liberties of citizens.\nThe extensive participation of citizens in making this basic law conveys the consensus to strengthen democracy and national unity, which flows from the collective wisdom of the people.',''),(2,'Structure','TITLE I. BASIC PRINCIPLES','TITLE I. BASIC PRINCIPLES','',''),(3,'Structure','CHAPTER I. THE REPUBLIC','CHAPTER I. THE REPUBLIC','',''),(4,'Articles','Article 1','Article 1. Republic of Mozambique','The Republic of Mozambique is an independent, sovereign, democratic State of  social justice.',''),(5,'Articles','Article 2','Article 2. Sovereignty and Legality','Sovereignty is vested in the people.\nThe Mozambican people shall exercise their sovereignty in the manner provided for in the Constitution.\nThe State is subordinate to the Constitution and is founded on legality.\nConstitutional rules shall prevail over all other rules of the legal order.',''),(6,'Articles','Article 3','Article 3. Democratic Rule of Law','The Republic of Mozambique is a State governed by the rule of law, based on pluralism of expression and democratic political organisation and on the respect for and guarantee of fundamental human rights and freedoms.',''),(7,'Articles','Article 4','Article 4. Legal Pluralism','The State recognises the different normative and dispute resolution systems that co-exist in Mozambican society, insofar as they are not contrary to the fundamental principles and values of the Constitution.',''),(8,'Articles','Article 5','Article 5. Nationality','Mozambican nationality may be by origin or it may be acquired.\nThe requirements for the attribution, acquisition, loss and re-acquisition of nationality are determined by the Constitution and regulated by law.',''),(9,'Articles','Article 6','Article 6. Territory','The territory of the Republic of Mozambique is a single whole, indivisible and inalienable, comprising the entire land surface, maritime zone and air space delimited by the national boundaries.\nThe breadth, limits and legal order of Mozambique’s territorial waters, the exclusive economic zone, the contiguous zone and seabed rights shall be fixed by law.',''),(10,'Articles','Article 7','Article 7. Territorial Organisation','The territory of the Republic of Mozambique shall be subdivided into provinces, districts, administrative posts, localities and settlements.\nUrban zones shall be classified either as cities or as towns.\nThe definition of the characteristics of territorial divisions, the creation of any new units, as well as the power to decide on politico-administrative organisation shall be fixed by law.',''),(11,'Articles','Article 8','Article 8. Unitary State','The Republic of Mozambique is a unitary State, which respects the principles of autonomy of local authorities (autarquias locais) in its organisation.',''),(12,'Articles','Article 9','Article 9. National Languages','The State shall esteem national languages as cultural and educational heritage, and shall promote their development and increasing use as languages that convey our identity.',''),(13,'Articles','Article 10','Article 10. Official Language','The official language in the Republic of Mozambique shall be Portuguese.',''),(14,'Articles','Article 11','Article 11. Fundamental Objectives','The fundamental objectives of the Republic of Mozambique shall be:\nthe defence of independence and sovereignty;\nthe consolidation of national unity;\nthe building of a society of social justice and the achievement of material and spiritual wellbeing and quality of life for its citizens;\nthe promotion of balanced economic, social and regional development in the country;\nthe defence and promotion of human rights and of the equality of citizens  before the law;\nthe strengthening of democracy, freedom, social stability and social and individual harmony;\nthe promotion of a society of pluralism, tolerance and a culture of peace;\nthe development of the economy and scientific and technological progress;\nthe affirmation of the Mozambican identity, of its traditions and other social and cultural values;\nthe establishment and development of relations of friendship and cooperation with other peoples and States.',''),(15,'Articles','Article 12','Article 12. Lay State','The Republic of Mozambique shall be a lay State.\nThe lay nature of the State rests on the separation between the State and religious denominations.\nReligious denominations shall have organisational freedom, freedom to carry out their functions and freedom of worship, and they shall conform to the laws of the State.\nThe State shall recognise and esteem the activities of religious denominations in order to promote a climate of understanding, tolerance and peace, the strengthening of national unity, the material and spiritual wellbeing of citizens, and economic and social development.',''),(16,'Articles','Article 13','Article 13. National Symbols','The symbols of the Republic of Mozambique shall be the national flag, emblem and anthem.',''),(17,'Articles','Article 14','Article 14. Age-old Resistance','The Republic of Mozambique shall esteem the heroic struggle and age-old resistance of the Mozambican people against foreign domination.',''),(18,'Articles','Article 15','Article 15. National Liberation, Defence of Sovereignty and Democracy','The Republic of Mozambique shall acknowledge and esteem the sacrifices made by those who gave their lives to the national liberation struggle and to the defence of the country’s sovereignty and democracy.\nThe State shall ensure the special protection of those who were disabled in the national liberation struggle, as well as the orphans and other dependants of those who died in this cause.\nThe Law shall determine how the rights established in this article are to be made effective.',''),(19,'Articles','Article 16','Article 16. War Disability','The State shall ensure special protection to those who were disabled during the armed conflict that ended with the signing of the General Peace Agreement in 1992, as well as the orphans and other direct dependants.\nThe State shall likewise protect those who have been disabled in the performance of public service or a humanitarian act.\nThe Law shall determine how the rights established in this article are to be made effective.',''),(20,'Structure','CHAPTER II. FOREIGN POLICY AND INTERNATIONAL LAW','CHAPTER II. FOREIGN POLICY AND INTERNATIONAL LAW','',''),(21,'Articles','Article 17','Article 17. International Relations','The Republic of Mozambique shall establish relations of friendship and cooperation with other States on the basis of mutual respect for sovereignty and territorial integrity, equality, non-interference in internal affairs and reciprocity of benefits.\nThe Republic of Mozambique shall accept, observe and apply the principles of the Charter of the United Nations and of the Charter of the Organisation of African Unity.',''),(22,'Articles','Article 18','Article 18. International Law','Validly approved and ratified International treaties and agreements shall enter into force in the Mozambican legal order once they have been officially published and while they are internationally binding on the Mozambican State.\nNorms of international law shall have the same force in the Mozambican legal order as have infra-constitutional legislative acts of the Assembly of the Republic and the Government, according to the respective manner in which they are received.',''),(23,'Articles','Article 19','Article 19. International Solidarity','The Republic of Mozambique shall be in solidarity with the struggle of the peoples and States of Africa, for unity, freedom, dignity and the right to economic and social progress.\nThe Republic of Mozambique shall seek to strengthen relations with countries engaged in the consolidation of their national independence, democracy and the recovery of the use and control of their natural wealth for their respective peoples.\nThe Republic of Mozambique shall join with all States struggling for the establishment of a just and equitable economic order in international relations.',''),(24,'Articles','Article 20','Article 20. Support for Freedom of Peoples and Asylum','The Republic of Mozambique shall support and be in solidarity with the struggles of peoples for their national liberation and for democracy.\nThe Republic of Mozambique shall grant asylum to foreigners persecuted on the grounds of their struggle for national liberation, for democracy, for peace and for the protection of human rights.\nThe law shall define political refugee status.',''),(25,'Articles','Article 21','Article 21. Special Ties of Friendship and Co-operation','The Republic of Mozambique shall maintain special ties of friendship and cooperation with the countries of the region, with countries whose official language is Portuguese and with countries that host Mozambican emigrants.',''),(26,'Articles','Article 22','Article 22. Policy of Peace','The Republic of Mozambique shall pursue a policy of peace and shall only resort to the use of force in the case of legitimate self-defence.\nThe Republic of Mozambique shall support the primacy of negotiated solutions to conflicts.\nThe Republic of Mozambique shall uphold the principle of general and universal disarmament of all States.\nThe Republic of Mozambique shall advocate the transformation of the Indian Ocean into a nuclear free zone of peace.',''),(27,'Structure','TITLE II. NATIONALITY','TITLE II. NATIONALITY','',''),(28,'Structure','CHAPTER I. NATIONALITY BY ORIGIN','CHAPTER I. NATIONALITY BY ORIGIN','',''),(29,'Articles','Article 23','Article 23. Jus Soli and Jus Sanguinis','The following persons shall, provided that they were born in Mozambique, be Mozambicans:\nThe children of a father or a mother who was born in Mozambique;\nChildren whose parents are stateless or of unknown nationality;\nThose who were domiciled in Mozambique at the time of independence and did not choose any other nationality, expressly or tacitly.\nThe children of a Mozambican father or mother working for the Mozambican State outside the country shall be Mozambicans, even if born abroad.\nThe children of a Mozambican father or mother shall be Mozambican, even if born abroad, provided that they have expressly declared, either on their own behalf, if over eighteen years of age, or through their legal representatives, if younger, that they wish to be Mozambican.',''),(30,'Articles','Article 24','Article 24. Jus Soli','Persons born in Mozambique after the proclamation of independence are Mozambican nationals.\nThis rule shall not apply to children born of a foreign father and a foreign mother, when either of them is in Mozambique in the employ of the government of his or her country.\nThe persons referred to in the preceding paragraph shall only have Mozambican nationality if they declare, for themselves if they are over eighteen years of age, or through their legal representatives if younger than this, that they wish to be Mozambican.\nThe time limit for the declaration referred to in the preceding paragraph is one year, counting from the date of birth of the interested party, where the declaration is made by his or her legal representative, or from his or her eighteenth birthday, where the declaration is made personally.',''),(31,'Articles','Article 25','Article 25. By Age of Majority','Persons who have met the requirements for nationality by origin but have not acquired such nationality by virtue of a choice made by their legal representatives, shall be Mozambican, provided that they are over eighteen years of age and that, within one year after attaining the age of majority, they personally declare that they wish to be Mozambican.',''),(32,'Structure','CHAPTER II. ACQUIRED NATIONALITY','CHAPTER II. ACQUIRED NATIONALITY','',''),(33,'Articles','Article 26','Article 26. By Marriage','A foreign person who has been married to a Mozambican citizen for at least five years acquires Mozambican nationality, except in cases of statelessness, provided that all of the following conditions are met:\nthat he or she declares that he or she wishes to acquire Mozambican nationality;\nthat he or she meets the requirements and offers the guarantees prescribed by law.\nThe nationality acquired by the spouse shall not be prejudiced by the declaration of annulment or dissolution of the marriage.',''),(34,'Articles','Article 27','Article 27. By Naturalisation','Mozambican nationality may be granted by naturalisation to foreigners who, at the time of submission of their application, meet all the following conditions:\nthat they have resided in Mozambique habitually and regularly for at least ten years;\nthat they are over eighteen years of age;\nthat they know Portuguese or a Mozambican language;\nthat they have command of their person and are capable of ensuring their own subsistence;\nthat they have civic probity;\nthat they meet the requirements and offer the guarantees prescribed by law.\nThe conditions set out in paragraphs a) and c) shall be waived for foreigners who have rendered relevant services to the Mozambican State, in the terms prescribed by law.',''),(35,'Articles','Article 28','Article 28. By Filiation','Mozambican nationality may be granted by means of naturalisation to the unmarried children, under eighteen years of age, of a citizen who has acquired Mozambican nationality.',''),(36,'Articles','Article 29','Article 29. By Adoption','A person who is adopted fully by a Mozambican national acquires Mozambican nationality.',''),(37,'Articles','Article 30','Article 30. Restrictions on the Performance of Functions','Citizens with acquired nationality may not be deputies or members of Government nor shall they be eligible for access to a diplomatic or military career.\nThe law shall define the conditions under which citizens who have acquired Mozambican nationality may perform public duties or private duties of public interest.',''),(38,'Structure','CHAPTER III. LOSS AND REACQUISITION OF NATIONALITY','CHAPTER III. LOSS AND REACQUISITION OF NATIONALITY','',''),(39,'Articles','Article 31','Article 31. Loss','Mozambican nationality shall be lost by a person who:\nbeing a national of another State, declares, in accordance with the proper procedures, that he or she does not wish to be Mozambican;\nhaving been given Mozambican nationality as a minor by virtue of a legal representative’s declaration, declares, in accordance with the proper procedures, and within one year of reaching the age of majority, that he or she does not wish to be Mozambican, provided that he or she can demonstrate possession of another nationality.',''),(40,'Articles','Article 32','Article 32. Reacquisition','Mozambican nationality may be granted to Mozambicans who, having lost such nationality now request it, provided that they meet all of the following conditions:\nthat they establish their domicile in Mozambique;\nthat they meet the requirements and offer the guarantees prescribed by law.\nA Mozambican woman who has lost her nationality through marriage may reacquire it by addressing a request to the competent authorities.\nReacquisition of nationality shall restore the legal situation prevailing prior to the loss of nationality.',''),(41,'Structure','CHAPTER IV. PREVAILING NATIONALITY AND REGISTRATIO','CHAPTER IV. PREVAILING NATIONALITY AND REGISTRATION','',''),(42,'Articles','Article 33','Article 33. Prevalence of Mozambican Nationality','No other nationality of persons who are Mozambican nationals under the terms of the law of the Republic of Mozambique shall be recognised or have any legal effect in the Mozambican legal order.',''),(43,'Articles','Article 34','Article 34. Registration','The registration and proof of acquisition, loss and reacquisition of Mozambican nationality shall be regulated by law.',''),(44,'Structure','TITLE III. FUNDAMENTAL RIGHTS, DUTIES AND FREEDOMS','TITLE III. FUNDAMENTAL RIGHTS, DUTIES AND FREEDOMS','',''),(45,'Structure','CHAPTER I. GENERAL PRINCIPLES','CHAPTER I. GENERAL PRINCIPLES','',''),(46,'Articles','Article 35','Article 35. Principle of Universality','All citizens are equal before the law, and they shall enjoy the same rights and be subject to the same duties, regardless of colour, race, sex, ethnic origin, place of birth, religion, level of education, social position, the marital status of their parents, their profession or their political preference.',''),(47,'Articles','Article 36','Article 36. Principle of Equality','Men and women shall be equal before the law in all spheres of political, economic, social and cultural life.',''),(48,'Articles','Article 37','Article 37. Disability','Disabled citizens shall enjoy fully the rights enshrined in the Constitution and shall be subject to the same duties, except those which their disability prevents them from exercising or fulfilling.',''),(49,'Articles','Article 38','Article 38. Duty to Respect the Constitution','All citizens shall have the duty to respect the constitutional order.\nActs contrary to the provisions of the Constitution shall be subject to punishment in terms of the law.',''),(50,'Articles','Article 39','Article 39. Acts against National Unity','All acts intended to undermine national unity, to disturb social harmony or to create divisions or situations of privilege or discrimination based on colour, race, sex, ethnic origin, place of birth, religion, level of education, social position, physical or mental ability, the marital status of one’s parents, profession or political preference, shall be punished in terms of the law',''),(51,'Articles','Article 40','Article 40. Right to Life','All citizens shall have the right to life and to physical and moral integrity, and they shall not be subjected to torture or to cruel or inhuman treatment.\nThere shall be no death penalty in the Republic of Mozambique.',''),(52,'Articles','Article 41','Article 41. Other Individual Rights','All citizens shall have the right to their honour, good name and their reputation, as well as the right to defend their public image and to protect their privacy.',''),(53,'Articles','Article 42','Article 42. Scope and Meaning of Fundamental Rights','The fundamental rights enshrined in the Constitution shall not exclude any other rights provided for by law.',''),(54,'Articles','Article 43','Article 43. Interpretation of Fundamental Rights','The constitutional principles in respect of fundamental rights shall be interpreted and integrated in harmony with the Universal Declaration of Human Rights and with the African Charter of Human and Peoples Rights.',''),(55,'Articles','Article 44','Article 44. Duties Towards One’s Fellow Beings','All individuals shall have the duty to respect and consider their fellow beings without any form of discrimination whatsoever, and to maintain relations with them aimed at promoting, safeguarding and strengthening respect, mutual tolerance and solidarity.',''),(56,'Articles','Article 45','Article 45. Duties Towards the Community','Every individual shall have the duty to:\nserve the national community, placing his or her physical and intellectual abilities at its service;\nwork to the best of his or her abilities and means;\npay contributions and taxes;\nadvocate, in his or her relations with the community, the preservation of cultural values, the spirit of tolerance and of dialogue and, in general, to contribute to civic education and advancement;\ndefend and promote health;\nprotect and conserve the environment;\ndefend and protect the public good and the good of the community.',''),(57,'Articles','Article 46','Article 46. Duties Towards the State','All citizens shall have the duty to contribute to the defence of the country.\nEvery individual shall also have the duty to fulfill his or her obligations under the law, and to obey orders that are issued by legitimate authorities in accordance with the terms of the Constitution and with respect for his or her fundamental rights.',''),(58,'Articles','Article 47','Article 47. Rights of Children','Children shall have the right to protection and the care required for their well being.\nChildren may express their opinion freely on issues that relate to them, according to their age and maturity.\nAll acts carried out by public entities or private institutions in respect of children shall take into account, primarily, the paramount interests of the child.',''),(59,'Structure','CHAPTER II. RIGHTS, DUTIES AND FREEDOMS','CHAPTER II. RIGHTS, DUTIES AND FREEDOMS','',''),(60,'Articles','Article 48','Article 48. Freedom of Expression and Information','All citizens shall have the right to freedom of expression and to freedom of the press, as well as the right to information.\nThe exercise of freedom of expression, which consists of the ability to impart one’s opinions by all lawful means, and the exercise of the right to information shall not be restricted by censorship.\nFreedom of the press shall include, in particular, the freedom of journalistic expression and creativity, access to sources of information, protection of independence and professional secrecy, and the right to establish newspapers, publications and other means of dissemination.\nIn the public sector media, the expression and confrontation of ideas from all currents of opinion shall be guaranteed.\nThe State shall guarantee the impartiality of the public sector media, as well as the independence of journalists from the Government, the Administration and other political powers.\nThe exercise of the rights and freedoms provided for in this article shall be governed by law on the basis of the imperative respect for the Constitution and for the dignity of the human person.',''),(61,'Articles','Article 49','Article 49. Broadcasting Rights, Right of Reply and of Political Response','Political parties shall, according to their degree of representation and to criteria prescribed by law, have the right to broadcasting time on public radio and television services.\nPolitical parties that have seats in the Assembly of the Republic but are not members of Government shall, in terms of the law and according to their degree of representation, have the right to broadcasting time on public radio and television services in order to exercise their right of reply and the right to respond to the political statements of the Government.\nTrade unions, professional organisations and organisations representing social and economic activities shall also be guaranteed broadcasting rights, according to criteria prescribed by law.\nDuring election periods, contestants shall have the right to regular and equitable broadcasting time on public radio and television stations of national or local range, within the terms of the law.',''),(62,'Articles','Article 50','Article 50. Superior Council for the Media','The Superior Council for the Media shall guarantee the right to information, to freedom of the press and to independence of the media, as well as the exercise of broadcasting rights and the right of reply.\nThe Superior Council for the Media shall be an independent body composed of eleven members appointed as follows:\ntwo members appointed by the President of the Republic, of whom one shall be the President;\nfive members elected by the Assembly of the Republic, according to the degree of parliamentary representation;\nthree representatives of journalists, elected by their respective professional organisations;\none representative of journalist businesses or institutions.\nThe Superior Council for the Media shall issue opinions prior to Government decisions on the licensing of private television and radio stations.\nThe Superior Council for the Media shall participate in the appointment and discharge of directors-general of public sector media organisations, in the terms of the law.\nThe law shall regulate the organisation, functioning and other powers of the Superior Council for the Media.',''),(63,'Articles','Article 51','Article 51. Right to Freedom of Assembly and Demonstration','All citizens shall have the right to freedom of assembly and demonstration, within the terms of the law.',''),(64,'Articles','Article 52','Article 52. Freedom of Association','All citizens shall enjoy freedom of association.\nSocial organisations and associations shall have the right to pursue their aims, to create institutions designed to achieve their specific objectives and to own assets in order to carry out their activities, in accordance with the law.\nArmed associations of a military or paramilitary nature, as well as associations that promote violence, racism, xenophobia or pursue aims that are against the law, shall be prohibited.',''),(65,'Articles','Article 53','Article 53. Freedom to Form, Participate in and Join Political Parties','All citizens shall have the freedom to form or to participate in political parties.\nParty membership shall be voluntary and shall stem from the freedom of citizens to associate on the basis of the same political ideals.',''),(66,'Articles','Article 54','Article 54. Freedom of Conscience, Religion and Worship','All citizens shall have the freedom to practice or not to practice a religion.\nNobody shall be discriminated against, persecuted, prejudiced, deprived of his or her rights, or benefit from or be exempt from duties, on the grounds of his faith or religious persuasion or practice.\nReligious denominations shall have the right to pursue their religious aims freely and to own and acquire assets for realising their objectives.\nThe protection of places of worship shall be ensured.\nThe right to conscientious objection shall be guaranteed in terms of the law.',''),(67,'Articles','Article 55','Article 55. Freedom of Residence and Movement','All citizens shall have the right to take up residence in any part of the national territory.\nAll citizens shall be free to travel inside the national territory and abroad, except those who have been legally deprived of this right by the courts.',''),(68,'Structure','CHAPTER III. INDIVIDUAL RIGHTS, FREEDOMS AND GUARA','CHAPTER III. INDIVIDUAL RIGHTS, FREEDOMS AND GUARANTEES','',''),(69,'Articles','Article 56','Article 56. General Principles','Individual rights and freedoms shall be directly applicable, shall bind both public and private entities, shall be guaranteed by the State, and shall be exercised within the Constitutional framework and the law.\nThe exercise of rights and freedoms may be restricted for the purposes of safeguarding other rights and interests that are protected by the Constitution.\nThe law may restrict rights, freedoms and guarantees only in cases expressly provided for in the Constitution.\nLegal restrictions on rights and freedoms shall be of a general and abstract nature and shall not have retroactive effect.',''),(70,'Articles','Article 57','Article 57. Non-Retroactivity','In the Republic of Mozambique laws may have retroactive effect only where this is to the benefit of citizens and other legal persons.',''),(71,'Articles','Article 58','Article 58. Right to Compensation and State Responsibility','Everyone shall have the right to claim compensation in accordance with the law, for damages caused by a violation of their fundamental rights.\nThe State shall be responsible for damages caused by the unlawful acts of its agents, in the performance of their functions, without prejudice to rights of recourse available under the law.',''),(72,'Articles','Article 59','Article 59. Right to Liberty and to Security','In the Republic of Mozambique everyone has the right to security and nobody shall be detained and put on trial except in accordance with the law.\nAccused persons shall enjoy a presumption of innocence until final court judgement has been passed.\nNo citizen shall be tried more than once for the same crime, nor shall a penalty be imposed that was not provided for, or is heavier than the one that was applicable, at the time when the criminal offence was committed.',''),(73,'Articles','Article 60','Article 60. Application of Criminal Law','Nobody shall be condemned for an act that did not constitute a criminal offence at the time when it was committed.\nCriminal law may be applied retroactively only in favour of the accused.',''),(74,'Articles','Article 61','Article 61. Restrictions on Penalties and Security Measures','Penalties and security measures that deprive or restrict freedom in perpetuity or for an unlimited or indefinite period shall be prohibited.\nPenalties are not transmissible.\nNo penalty shall deprive persons of any of their civil, professional or political rights, nor shall any penalty deprive a convicted person of his or her fundamental rights, except insofar as the restrictions are inherent to the conviction and are specifically necessary for the execution of the sentence.',''),(75,'Articles','Article 62','Article 62. Access to Courts','The State shall guarantee that citizens have access to the courts and that persons charged with a crime have the right to defence and the right to legal assistance and aid.\nThe accused shall have the right freely to choose a defence counsel to assist in all acts of the proceedings. It shall be ensured that adequate legal assistance and aid is given to accused persons who, for economic reasons, are unable to engage their own attorney.',''),(76,'Articles','Article 63','Article 63. Attorneyship and Advocacy','The State shall ensure that attorneys at law are given the immunity necessary for the performance of their functions, and shall regulate legal representation in court as a fundamental element of the administration of justice.\nIn the performance of an attorney’s functions, documents, correspondence and other items that have been entrusted to the attorney by his or her client, have been obtained for the defence of the client or pertain to his or her profession, shall be inviolable, within legal limits.\nSearches, seizures and other similar measures against an attorney’s offices or files may only be executed by order of a court and shall be performed in the presence of the ordering judge, the attorney and one representative of the bar association appointed by the association for this purpose, when the commission of an unlawful act punishable by a term of imprisonment longer than two years is involved and there is evidence to attribute the commission of the act to the attorney.\nAn attorney shall have the right to communicate personally and privately with his or her client, even when such client is imprisoned or detained in a civil or military institution.\nThe law shall regulate all other matters pertaining to attorneyship and advocacy.',''),(77,'Articles','Article 64','Article 64. Preventive Imprisonment','Preventive imprisonment shall be permitted only in cases provided for by the law, which shall determine the duration of such imprisonment.\nCitizens held in preventive imprisonment shall, within the period fixed by law, be brought before the judicial authorities who alone shall have the power to decide on the lawfulness and continuation of the imprisonment.\nEveryone deprived of their liberty shall be informed promptly and in a way that they understand of the reasons for their imprisonment or detention and of their rights.\nThe judicial decision by which an imprisonment or detention is ordered or maintained shall be communicated at once to a relative or trusted acquaintance of the detainee, as indicated by the detainee.',''),(78,'Articles','Article 65','Article 65. Principles of Criminal Process','In criminal process, the right to defence and to trial is an inviolable right guaranteed to every accused.\nCriminal trial hearings shall be public, except in so far as it is prudent to exclude or restrict publicity in order to safeguard personal, family, social or moral privacy, or for material reasons of trial security or public order.\nAll evidence obtained through the use of torture, coercion, offences against the physical or moral integrity of the person, the abusive intrusion into their private and family life or into their home, correspondence or telecommunications, shall be invalid.\nNo case may be withdrawn from a court whose competence is established by an earlier law, except in cases specifically provided for by law.',''),(79,'Articles','Article 66','Article 66. Habeas corpus','In the case of unlawful imprisonment or detention, the citizen shall have the right to interpose a writ of habeas corpus.\nThe writ of habeas corpus shall be interposed before a court, which shall decide on the matter within a period not longer than eight days.',''),(80,'Articles','Article 67','Article 67. Extradition','Extradition may take place only pursuant to a court decision.\nExtradition for political reasons shall not be authorised.\nExtradition shall not be permitted for crimes which are punishable by death or by perpetual imprisonment under the law of the requesting State, or when there are grounds to believe that the extradited person may be subjected to torture or inhumane, degrading or cruel treatment.\nNo Mozambican citizen may be expelled or extradited from the national territory.',''),(81,'Articles','Article 68','Article 68. Inviolability of the Home and of Correspondence','The home and the correspondence or other forms of private communication shall be inviolable, except in cases specifically provided for by law.\nEntry into the home of a citizen against the citizen’s will may be ordered only by the competent judicial authorities, in such instances and according to such procedures as are specifically established by law.\nNobody shall enter the home of any person during the night without that person’s consent.',''),(82,'Articles','Article 69','Article 69. Right to Contest','Every citizen shall be entitled to contest those acts that violate their rights established in the Constitution and the laws.',''),(83,'Articles','Article 70','Article 70. Right of Recourse to the Courts','Every citizen shall have the right of recourse to the courts against acts that violate their rights and interests recognised by the Constitution and the laws.',''),(84,'Articles','Article 71','Article 71. Use of Computerised Data','The use of computerised means for recording and processing individually identifiable data in respect of political, philosophical or ideological beliefs, of religious faith, party or trade union affiliation or private lives, shall be prohibited.\nThe law shall regulate the protection of personal data kept on computerized records, the conditions of access to data banks, and the creation and use of such data banks and information stored on computerised media by public authorities and private entities.\nAccess to data bases or to computerised archives, files and records for obtaining information on the personal data of third parties, as well as the transfer of personal data from one computerised file to another that belongs to a distinct service or institution, shall be prohibited except in cases provided for by law or by judicial decision.\nAll persons shall be entitled to have access to collected data that relates to them and to have such data rectified.',''),(85,'Articles','Article 72','Article 72. Suspension of Rights','Individual freedoms and guarantees may be temporarily suspended or restricted only in the event of a declaration of a state of war, of a state of siege, or of a state of emergency, in accordance with the terms of the Constitution.\nWhenever there is a suspension or restriction of freedoms or guarantees, such suspension or restriction shall be general and abstract, and the duration and the legal grounds on which it is founded shall be specified.',''),(86,'Structure','CHAPTER IV. POLITICAL RIGHTS, FREEDOMS AND GUARANT','CHAPTER IV. POLITICAL RIGHTS, FREEDOMS AND GUARANTEES','',''),(87,'Articles','Article 73','Article 73. Universal Suffrage','The Mozambican people shall exercise political power through elections of their representatives by universal, direct, equal and periodic suffrage and by secret ballot, through referenda on major national issues, and through the permanent democratic participation of citizens in the affairs of the nation.',''),(88,'Articles','Article 74','Article 74. Political Parties and Pluralism','Parties shall be the expression of political pluralism; they shall contribute to the formation and manifestation of the will of the people and shall be fundamental instruments of democratic participation by citizens in the governing of the country.\nThe internal structure and the operation of political parties shall be democratic.',''),(89,'Articles','Article 75','Article 75. Formation of Political Parties','In deep respect for national unity and democratic values, political parties shall be bound by the principles enshrined in the Constitution and in the law.\nIn their formation and in the realisation of their objectives, political parties shall, in particular:\nbe national in scope;\ndefend national interests;\ncontribute to the formation of public opinion, particularly on major national issues;\nstrengthen the patriotic spirit of citizens and the consolidation of the Mozambican Nation.\nParties shall contribute towards peace and stability in the country through the political and civic education of citizens.\nThe formation, structure and operation of parties shall be regulated by law.',''),(90,'Articles','Article 76','Article 76. Names','Political parties shall be prohibited from using names containing expressions that are directly related to any religious denominations or churches, and from using emblems that may be confused with national or religious symbols.',''),(91,'Articles','Article 77','Article 77. Resorting to Armed Violence','Political parties shall be prohibited from advocating or resorting to armed violence in order to change the political or social order of the country.',''),(92,'Articles','Article 78','Article 78. Social Organisations','Social organisations, as associations with their own interests and affinities, play an important role in promoting democracy and in the participation of citizens in public affairs.\nSocial organisations contribute to achieving the rights and freedoms of citizens, as well as towards raising individual and collective awareness in the fulfilment of civic duties.',''),(93,'Articles','Article 79','Article 79. Right of Petition, Complaint and Claim','All citizens shall have the right to present petitions, complaints and claims to the competent authority in order to demand the restitution of their rights violated or in defence of the public interest.',''),(94,'Articles','Article 80','Article 80. Right of Resistance','All citizens shall have the right not to comply with orders that are unlawful or that infringe on their rights, freedoms and guarantees.',''),(95,'Articles','Article 81','Article 81. Right of Popular Action','All citizens shall have the right to popular action in accordance with the law, either personally or through associations for defending the interests in question.\nThe right of popular action shall consist of:\nthe right to claim for the injured party or parties such compensation as they are entitled to;\nThe right to advocate the prevention, termination or judicial prosecution of offences against the public health, consumer rights, environmental conservation and cultural heritage;\nThe right to defend the property of the State and of local authorities.',''),(96,'Structure','CHAPTER V. ECONOMIC, SOCIAL AND CULTURAL RIGHTS AN','CHAPTER V. ECONOMIC, SOCIAL AND CULTURAL RIGHTS AND DUTIES','',''),(97,'Articles','Article 82','Article 82. Right of Ownership','The State shall recognise and guarantee the right of ownership of property.\nExpropriation may take place only for reasons of public necessity, utility, or interest, as defined in the terms of the law, and subject to payment of fair compensation.',''),(98,'Articles','Article 83','Article 83. Right of Inheritance','The State recognises and guarantees, in accordance with the law, the right of inheritance.',''),(99,'Articles','Article 84','Article 84. Right to Work','Work shall be a right and a duty of every citizen.\nAll citizens shall have the right freely to choose their profession.\nForced labour shall be prohibited, except where the work is performed within the framework of penal legislation.',''),(100,'Articles','Article 85','Article 85. Right to Retribution and to Safety at Work','All workers shall have the right to fair remuneration, rest and vacation and to retirement in accordance with the law.\nWorkers shall have the right to protection, health and safety at work.\nWorkers may be dismissed only in the cases and in accordance with the terms provided for by law.',''),(101,'Articles','Article 86','Article 86. Freedom of Professional Associations and Unions','All workers shall have the freedom to organise professional associations or trade unions.\nProfessional associations and trade unions shall be governed by the principles of democratic organisation and management, based on the active participation of their members in all of their activities, and on the periodic election of their bodies by secret ballot.\nProfessional associations and trade unions shall be independent from employers, from the State, from political parties and from churches or religious denominations.\nThe law shall regulate the creation, merger, alliance and dissolution of professional associations and trade unions, as well as the guarantees of their autonomy and independence from employers, from the State, from political parties and from churches and religious denominations.',''),(102,'Articles','Article 87','Article 87. Right to Strike and Prohibition of Lock Outs','Workers shall have the right to strike, and the law shall regulate the exercise of this right.\nThe law shall restrict the exercise of the right to strike in essential services and activities, in the interest of the pressing needs of society and of national security.\nLock outs shall be prohibited.',''),(103,'Articles','Article 88','Article 88. Right to Education','In the Republic of Mozambique, education shall be a right and a duty of all citizens.\nThe State shall promote the extension of education to professional and continuing vocational training, as well as equal access to the enjoyment of this right by all citizens.',''),(104,'Articles','Article 89','Article 89. Health','All citizens shall have the right to medical and health care, within the terms of the law, and shall have the duty to promote and protect public health.',''),(105,'Articles','Article 90','Article 90. Right to a Balanced Environment','All citizens shall have the right live in a balanced environment and shall have the duty to defend it.\nThe State and the local authorities, with collaboration from associations for environmental protection, shall adopt policies to protect the environment and shall promote the rational use of all natural resources.',''),(106,'Articles','Article 91','Article 91. Housing and Urbanisation','All citizens shall have the right to a suitable home, and it shall be the duty of the State, in accordance with national economic development, to create the appropriate institutional, normative and infra-structural conditions.\nThe State shall also be responsible for funding and supporting the initiatives of the local communities, the local authorities and the people, in order to promote private and cooperative construction as well the accessibility of home ownership.',''),(107,'Articles','Article 92','Article 92. Rights of Consumers','Consumers shall have the right to quality in the goods and services that they consume, to education and information, to the protection of their health, to the safeguarding of their economic interests and to reparation for damage.\nAdvertising shall be regulated by law and all forms of hidden, indirect and misleading advertising shall be prohibited.\nConsumer associations and co-operatives shall have the right, within the terms of the law, to State assistance, the right to be heard on issues concerning consumer protection, and title to sue in order to defend the interests of their members.',''),(108,'Articles','Article 93','Article 93. Physical Culture and Sport','Citizens shall have the right to physical education and to sport.\nThe State shall encourage, through educational and sporting institutions, the practice and the dissemination of physical education and sport.',''),(109,'Articles','Article 94','Article 94. Freedom of Cultural Creativity','All citizens shall have the right to freedom of scientific, technical, literary and artistic creativity.\nThe State shall protect rights relating to intellectual property, including copyright, and shall promote the practice and dissemination of literature and art.',''),(110,'Articles','Article 95','Article 95. Right to Assistance of the Disabled and the Aged','All citizens shall have the right to assistance in the case of disability or old age.\nThe State shall promote and encourage the creation of conditions for realizing this right.',''),(111,'Structure','TITLE IV. ECONOMIC, SOCIAL, FINANCIAL AND FISCAL O','TITLE IV. ECONOMIC, SOCIAL, FINANCIAL AND FISCAL ORGANISATION','',''),(112,'Structure','CHAPTER I. GENERAL PRINCIPLES','CHAPTER I. GENERAL PRINCIPLES','',''),(113,'Articles','Article 96','Article 96. Economic Policy','The State economic policy shall be directed towards laying the fundamental bases for development, improving the living conditions of the people, strengthening the sovereignty of the State, and consolidating national unity, through the participation of citizens and the efficient use of human and material resources.\nWithout prejudice to balanced development, the State shall guarantee the distribution of national wealth and it shall recognise and esteem the role of productive zones.',''),(114,'Articles','Article 97','Article 97. Fundamental Principles','The economic and social order of the Republic of Mozambique shall aim to satisfy the basic needs of the people and to promote social wellbeing, and shall be based on the following fundamental principles:\non the value of labour;\non market forces;\non the initiatives of economic operators;\non the co-existence of the public sector, the private sector and the social and co-operative sector;\non public ownership of natural resources and means of production, in accordance with the collective interest;\non the protection of the co-operative and social sector;\non the action of the State as regulator and promoter of economic and social growth and development.',''),(115,'Articles','Article 98','Article 98. State Property and Public Domain','Natural resources in the soil and the subsoil, in inland waters, in the territorial sea, on the continental shelf and in the exclusive economic zone shall be the property of the State.\nThe public domain of the State shall comprise:\nthe maritime zone;\nthe airspace;\narchaeological heritage;\nnature conservation zones;\nhydraulic resources;\nenergy resources;\nroads and railways;\nmineral deposits;\nother property classified as such by law.\nThe law shall regulate the legal regime of property in the public domain, as well as its management and conservation, and shall distinguish between the public domain of the state, the public domain of local authorities and the public domain of communities, with due respect for the principles of imprescriptibility and immunity from seizure.',''),(116,'Articles','Article 99','Article 99. Sectors of Ownership of the Means of Production','The national economy shall guarantee the coexistence of three sectors of ownership of the means of production.\nThe public sector consists of those means of production the ownership and management of which belong to the State or other public entities.\nThe private sector consists of those means of production the ownership and management of which belong to private individual or corporate persons, without prejudice to the following paragraph.\nThe co-operative and social sector comprises, specifically:\ncommunity means of production, held and managed by local communities;\nmeans of production exploited collectively by workers;\nmeans of production held and managed by not-for-profit corporate persons whose main objective is social solidarity, specifically those of a mutual nature.',''),(117,'Articles','Article 100','Article 100. Taxes','Taxes shall be established and modified by law, and shall be set according to criteria of social justice.',''),(118,'Structure','CHAPTER II. ECONOMIC ORGANISATION','CHAPTER II. ECONOMIC ORGANISATION','',''),(119,'Articles','Article 101','Article 101. Co-ordination of Economic Activity','The State shall promote, co-ordinate and supervise economic activity, acting directly or indirectly to resolve the basic problems of the people and to reduce social and regional inequalities.\nState investment shall play a driving role in promoting balanced development.',''),(120,'Articles','Article 102','Article 102. Natural Resources','The State shall promote knowledge, survey and valorisation of natural resources, and shall determine the conditions under which they may be used and developed subject to national interests.',''),(121,'Articles','Article 103','Article 103. Agriculture','In the Republic of Mozambique, agriculture shall be the basis for national development.\nThe State shall guarantee and promote rural development in order to meet the growing and diverse needs of the people, and for the economic and social progress of the country.',''),(122,'Articles','Article 104','Article 104. Industry','In the Republic of Mozambique, industry shall be the driving force for the national economy.',''),(123,'Articles','Article 105','Article 105. Family Sector','The family sector shall play a fundamental role in meeting the basic needs of the people.\nThe State shall support and provide incentives for family sector production, and shall encourage peasants as well as individual workers to organize themselves into more advanced forms of production.',''),(124,'Articles','Article 106','Article 106. Small Scale Production','The State shall recognise the contribution made by small scale production to the national economy, and shall support its development as a way of making good use of the capacity and the creativity of the people.',''),(125,'Articles','Article 107','Article 107. National Business Sector','The State shall promote and support the active participation of the national business sector in the development and consolidation of the country’s economy.\nThe State shall create incentives to provide for the growth of the national business sector throughout the country, particularly in rural zones.',''),(126,'Articles','Article 108','Article 108. Foreign Investment','The State shall guarantee foreign investment, which shall operate within the framework of State economic policy.\nForeign ventures shall be permitted in all of the national territory and in all economic sectors, except those that are reserved exclusively for ownership or development by the State.',''),(127,'Articles','Article 109','Article 109. Land','All ownership of land shall vest in the State.\nLand may not be sold or otherwise disposed of, nor may it be mortgaged or subject to attachment.\nAs a universal means for the creation of wealth and of social well being, the use and enjoyment of land shall be the right of all the Mozambican people.',''),(128,'Articles','Article 110','Article 110. Use and Enjoyment of Land','The State shall determine the conditions under which land may be used and enjoyed.\nThe right to use and benefit from land shall be granted to individual or corporate persons, taking into account its social or economic purpose.',''),(129,'Articles','Article 111','Article 111. Rights Acquired Through Inheritance or Occupation of Land','In granting titles for the use and enjoyment of land, the State shall recognise and protect rights acquired through inheritance or by occupation, unless there is a legal reservation or the land has been lawfully granted to another person or entity.',''),(130,'Structure','CHAPTER III. SOCIAL ORGANISATION','CHAPTER III. SOCIAL ORGANISATION','',''),(131,'Articles','Article 112','Article 112. Labour','Labour is the driving force of development and shall merit respect and protection.\nThe State shall promote the fair distribution of the proceeds of labour.\nThe State maintains that everyone should receive equal pay for equal work.',''),(132,'Articles','Article 113','Article 113. Education','The Republic of Mozambique shall promote an educational strategy that aims towards national unity, wiping out illiteracy, mastering science and technology, and providing citizens with moral and civic values.\nThe State shall organise and develop education through a national system of education.\nPublic education shall not pertain to any religion.\nEducation provided by collective and other private entities shall be administered in accordance with the law and shall be subject to State control.\nThe State shall not plan education and culture in accordance with any specific philosophical, aesthetic, political, ideological or religious guidelines.',''),(133,'Articles','Article 114','Article 114. Higher Education','Access to public institutions of higher education shall guarantee equal and equitable opportunities and the democratisation of education, taking into account the requirements in terms of qualified staff and the raising of educational and scientific standards of the country.\nPublic institutions of higher education shall be corporate persons governed by public law, and they shall have legal personality and enjoy scientific, teaching, financial and administrative autonomy, without prejudice to the appropriate evaluation of teaching standards, in accordance with the law.\nThe State shall recognise and supervise private and co-operative education in accordance with the law.',''),(134,'Articles','Article 115','Article 115. Culture','The State shall promote the development of national culture and identity and shall guarantee free expression of the traditions and values of Mozambican society.\nThe State shall promote the dissemination of Mozambican culture and shall take action to enable the Mozambican people to benefit from the cultural achievements of other peoples.',''),(135,'Articles','Article 116','Article 116. Health','Medical and health care for citizens shall be organised through a national health system, which shall benefit all Mozambican people.\nTo achieve the goals of the national health system, the law shall establish the ways in which medical and health care is delivered.\nThe State shall encourage citizens and institutions to participate in raising the standard of health in the community.\nThe State shall promote the expansion of medical and health care and the equal access of all citizens to the enjoyment of this right.\nThe State shall be responsible for promoting, supervising and controlling the production, the sale and the use of chemical, biological and pharmaceutical products and other forms of treatment and diagnosis.\nThe medical and health care activities run by collective and private entities shall be carried out in accordance with the law and be subject to the supervision of the State.',''),(136,'Articles','Article 117','Article 117. Environment and Quality of Life','The State shall promote efforts to guarantee the ecological balance and the conservation and preservation of the environment, with a view to improving the quality of life of its citizens.\nWith a view to guaranteeing the right to the environment within the framework of sustainable development, the State shall adopt policies aimed at:\npreventing and controlling pollution and erosion;\nintegrating environmental objectives with sectoral policies;\npromoting the integration of environmental values into educational policies and programmes;\nguaranteeing the rational utilisation of natural resources and the safeguarding of their capacity to regenerate, ecological stability and the rights of future generations;\npromoting territorial ordinance with a view to ensuring the correct location of activities, and balanced socio-economic development.',''),(137,'Articles','Article 118','Article 118. Traditional Authority','The State shall recognise and esteem traditional authority that is legitimate according to the people and to customary law.\nThe State shall define the relationship between traditional authority and other institutions and the part that traditional authority should play in the economic, social and cultural affairs of the country, in accordance with the law.',''),(138,'Articles','Article 119','Article 119. Family','The family is the fundamental unit and the basis of society.\nThe State shall, in accordance with the law, recognise and protect marriage as the institution that secures the pursuit of family objectives.\nIn the context of the development of social relations based on respect for human dignity, the State shall guarantee the principle that marriage is based on free consent.\nThe law shall establish forms in which traditional and religious marriage shall be esteemed, and determine the registration requirements and effects of such marriage.',''),(139,'Articles','Article 120','Article 120. Motherhood and Fatherhood','Motherhood and fatherhood shall be afforded dignity and protection.\nThe family shall be responsible for raising children in a harmonious manner, and shall teach the new generations moral, ethical and social values.\nThe family and the State shall ensure the education of children, bringing them up in the values of national unity, love for the motherland, equality among men and women, respect and social solidarity.\nFathers and mothers shall support children born out of wedlock and those born in wedlock.',''),(140,'Articles','Article 121','Article 121. Childhood','All children have the right to protection from the family, from society and from the State, having in mind their full development.\nChildren, in particular orphans and disabled and abandoned children, shall be protected by the family, by society and by the State against all forms of discrimination, ill treatment and the abusive use of authority within the family and in other institutions.\nChildren shall not be discriminated against on the grounds of their birth, nor shall they be subjected to ill treatment.\nChild labour shall be prohibited, whether the children are of compulsory school going age or any other age.',''),(141,'Articles','Article 122','Article 122. Women','The State shall promote, support and value the development of women, and shall encourage their growing role in society, in all spheres of political, economic, social and cultural life of the country.\nThe State shall recognise and hold in high esteem the participation of women in the national liberation struggle and in the defence of sovereignty and democracy.',''),(142,'Articles','Article 123','Article 123. Youth','Young people, honourably upholding the patriotic traditions of the Mozambican people, played a decisive role in the national liberation struggle and the struggle for democracy, and they constitute a force for the renewal of society.\nState policy shall be directed particularly towards ensuring the harmonious development of the character of young people, to helping them acquire a taste for free and creative work, to developing their sense of serving the community, and to providing appropriate conditions for their entering into active life.\nThe State shall promote, support and encourage young people’s initiatives in consolidating national unity, and in the reconstruction, the development and the defence of the country.\nThe State and society shall stimulate and support the creation of youth organisations for the pursuit of cultural, artistic, recreational, sporting and educational objectives.\nThe State, acting in co-operation with associations representing parents and persons in charge of education, and with private institutions and youth organisations, shall adopt a national youth policy capable of promoting and supporting the professional training of young people, their access to first jobs and free intellectual and physical development.',''),(143,'Articles','Article 124','Article 124. Elderly','The elderly shall have the right to special protection by their family, society and the State, particularly through the creation of housing conditions, by living in togetherness with the family and the community, and by being received at public and private institutions, thereby preventing them from becoming marginalized.\nThe State shall promote a policy for the elderly that integrates economic, social and cultural action, with a view to creating opportunities for personal achievement through their involvement in the life of the community.',''),(144,'Articles','Article 125','Article 125. Disabled','The disabled shall have a right to special protection by the family, the society and the State.\nThe State shall promote the creation of conditions for learning and developing sign language.\nThe State shall promote the creation of conditions necessary for the economic and social integration of the disabled.\nThe State shall promote, in co-operation with associations of the disabled and with private entities, a policy that will guarantee:\nthe rehabilitation and integration of the disabled;\nthe creation of appropriate conditions to prevent them from becoming socially isolated and marginalized;\npriority treatment of disabled citizens by public and private services;\neasy access to public places.\nThe State shall encourage the establishment of associations of the disabled.',''),(145,'Structure','CHAPTER VI. FINANCIAL AND TAX SYSTEM','CHAPTER VI. FINANCIAL AND TAX SYSTEM','',''),(146,'Articles','Article 126','Article 126. Financial System','The financial system shall be organised in such a way as to guarantee that savings are formed, deposited and secure and that financial measures required for the country’s economic and social development are applied.',''),(147,'Articles','Article 127','Article 127. Tax System','The tax system shall be structured in order to meet the financial needs of the State and other public bodies, achieve the objectives of the State’s economic policy, and guarantee the fair distribution of income and wealth.\nTaxes shall be established and modified by law, which shall stipulate tax incidence and tax rates, and fiscal benefits and guarantees afforded to taxpayers.\nNobody may be compelled to pay taxes that have not been established in accordance with the Constitution, and which are not assessed and collected in terms of the law.\nDuring the course of the same financial year, the bases of tax incidence and tax rates may not be increased.\nTax law shall not have retroactive effect, except where this would be more favourable to the taxpayer.',''),(148,'Articles','Article 128','Article 128. Economic and Social Plan','The purpose of the Economic and Social Plan is to guide economic and social development towards sustainable growth, to reduce regional imbalances and progressively to eliminate economic and social differences between cities and the countryside.\nThe Economic and Social Plan shall be expressed financially in the State Budget.\nThe draft Economic and Social Plan shall be submitted to the Assembly of the Republic, together with reports on the major global and sectoral options, including information to substantiate them.',''),(149,'Articles','Article 129','Article 129. Drafting and Execution of the Economic and Social Plan','The Government shall draft the Economic and Social Plan on the basis of its five-year programme.\nThe draft Economic and Social Plan shall be submitted to the Assembly of the Republic and shall contain a forecast of the macroeconomic aggregates and the actions to be taken in pursuit of the sectoral development goals, and it shall be accompanied by implementation reports to substantiate it.\nThe drafting and implementation of the Economic and Social Plan shall be decentralised by province and by sector.',''),(150,'Articles','Article 130','Article 130. State Budget','The budget shall be unitary, shall specify revenue and expenditure, and shall at all times respect the rules on annual publication and on publicity, in accordance with the law.\nThe budget may comprise multi-annual programmes or projects, in which case the budget shall present the expenditure in respect of the particular year to which it refers.\nThe State Budget bill shall be drafted by the Government and presented to the Assembly of the Republic, and it shall contain information to substantiate revenue forecasts, limits on expenditure, deficit financing, as well as all information to substantiate budgetary policy.\nThe law shall determine the rules for implementation of the budget, and shall establish the criteria according to which the budget may be modified, the implementation period, as well as the procedures to be followed when the deadlines for presentation of the budget or voting on it cannot be met.',''),(151,'Articles','Article 131','Article 131. Supervision','The Administrative Court and the Assembly of the Republic shall supervise the implementation of the State Budget, and the Assembly of the Republic shall appraise and decide on the General State Account after it has received the opinion of the Administrative Court.',''),(152,'Articles','Article 132','Article 132. Central Bank','The Bank of Mozambique is the Central Bank of the Republic of Mozambique.\nThe operation of the Bank of Mozambique shall be governed by specific legislation and by international norms that bind the Republic of Mozambique and apply to it.',''),(153,'Structure','TITLE V. ORGANISATION OF POLITICAL POWER','TITLE V. ORGANISATION OF POLITICAL POWER','SOLE CHAPTER. GENERAL PRINCIPLES',''),(154,'Articles','Article 133','Article 133. Sovereign Public Offices','The sovereign public offices are: the President of the Republic, the Assembly of the Republic, the Government, the courts and the Constitutional Council.',''),(155,'Articles','Article 134','Article 134. Separation and Interdependence','The sovereign public offices are established on the principles of separation and interdependence of powers enshrined in the Constitution, and shall owe obedience to the Constitution and the laws.',''),(156,'Articles','Article 135','Article 135. General Principles of the Electoral System','The general rule shall be that the appointment of elective sovereign public offices and elective local and provincial offices shall take place through universal, direct, equal and periodic suffrage and by personal and secret ballot.\nResults of elections shall be calculated according to the system of proportional representation.\nVoter registration and electoral activity shall be the supervised by an independent and impartial body, the composition, organisation, operation and powers of which shall be established by law.\nThe electoral procedures shall be regulated by law.',''),(157,'Articles','Article 136','Article 136. Referenda','Citizens who have been registered as voters within the national territory, and those living abroad who have been properly registered as voters, may be called to take part in referenda on major national issues.\nThe decision to call a referendum shall be taken by the President of the Republic upon the recommendation of the Assembly of the Republic, approved by an absolute majority of its members and on the initiative of at least one third of the deputies.\nThe following matters may not be the subject of referenda:\nAmendments to the Constitution, with the exception of those in article 292 (1);\nMatters referred to in article 179 (2).\nIf the matters referred to in article 179 (2) are the subject of an international convention, they may be submitted to a referendum, except where they concern peace and the changing of boundaries.\nNo referendum shall be called or held during the period between the calling and the holding of a general election for sovereign public offices.\nA referendum shall be considered valid and binding only where at least half of the registered voters have voted in it.\nIn addition to the relevant provisions of the electoral law, specific legislation shall establish the conditions for setting up and for holding referenda.',''),(158,'Articles','Article 137','Article 137. Incompatibility','The offices of President of the Republic, President of the Assembly of the Republic, Prime Minister, President of the Supreme Court, President of the Constitutional Council, President of the Administrative Court, Attorney General of the Republic, Ombudsman, Vice President of the Supreme Court, Deputy Attorney General of the Republic, Deputy, Deputy Minister, Secretary of State, Provincial Governor, District Administrator, military personnel in active service shall be mutually incompatible.\nThe position of member of Government shall likewise be incompatible with the offices referred to in the preceding paragraph, with the exception of those of the President of the Republic and the Prime Minister.\nThe law shall define other incompatibilities, including incompatibilities between public offices and private duties.',''),(159,'Articles','Article 138','Article 138. Central Offices','Central State offices are: the sovereign public offices, governmental bodies as a whole, and such institutions as are responsible for guaranteeing that national interests prevail and that a unitary State policy is implemented.',''),(160,'Articles','Article 139','Article 139. Powers of Central Offices','Central State offices shall, in general, have power to exercise sovereign functions, to regulate matters in accordance with the law, and to define national policies.\nThe central offices shall have exclusive powers in the following matters: representation of the State, definition and organisation of the territory, national defence, public order, supervision of borders, issuing of currency, and diplomatic relations.',''),(161,'Articles','Article 140','Article 140. Heads and Agents of Public Offices','Central offices shall take action directly, or through appointed heads or agents of the administration, who shall supervise central activities within a particular territorial area.\nThe law shall determine the form, organisation and powers for the exercise of Public Administration.',''),(162,'Articles','Article 141','Article 141. Provincial Government','The representative of the Government at provincial level is the Provincial Governor.\nThe Provincial Government is the body charged with ensuring the implementation, at provincial level, of centrally defined Government policies, and it shall exercise administrative supervision over local authorities, in accordance with the law.\nMembers of the Provincial Government shall be appointed by the Ministers responsible for the particular portfolios, in consultation with the Provincial Governor.\nThe organisation, composition, functioning and powers of Provincial Government shall be defined by law.',''),(163,'Articles','Article 142','Article 142. Provincial Assemblies','Provincial assemblies shall be democratically representative bodies elected by universal, direct suffrage and by secret ballot, in accordance the principle of proportional representation, and their terms of office shall be five years.\nProvincial assemblies shall, in particular, have the power to:\nsupervise and monitor adherence to principles and norms established in the Constitution and in the laws, as well as the observance of decisions of the Council of Ministers relating to the particular province;\napprove the Provincial Government programme and supervise and monitor compliance with it.\nThe composition, organisation, operation and other powers shall be defined by law.',''),(164,'Articles','Article 143','Article 143. Normative Acts','Legislative acts shall consist of laws and decree-laws.\nActs of the Assembly of the Republic shall take the form of laws, motions and resolutions.\nDecree-laws are legislative acts passed by the Council of Ministers pursuant to authorisation from the Assembly of the Republic.\nRegulatory acts of the Government shall take the form of Decrees, whether they are made under the authority of a regulatory law or are made as autonomous regulations.\nActs of the Governor of the Bank of Mozambique, in the exercise of his powers, shall take the form of notices.',''),(165,'Articles','Article 144','Article 144. Publicity','The following shall be published in the Boletim da República (Government Gazette), under pain of having no legal effect:\nlaws, motions and resolutions of the Assembly of the Republic;\ndecrees of the President of the Republic;\ndecree-laws, decrees, resolutions and other legal instruments issued by the Government;\ndecisions of the Supreme Court and judgements of the Constitutional Council, as well as the decisions of other courts to which the law attributes general binding force;\njudgements on the results of elections and national referenda; f) resolutions ratifying international treaties and agreements; g) notices issued by the Governor of the Bank of Mozambique.\nThe law shall define the publicity requirements applicable to other public legal instruments.',''),(166,'Articles','Article 145','Article 145. Representation of Central Offices','The state offices shall insure that they are represented at all territorial levels.',''),(167,'Structure','TITLE VI. PRESIDENT OF THE REPUBLIC','TITLE VI. PRESIDENT OF THE REPUBLIC','',''),(168,'Structure','CHAPTER I. STATUTE AND APPOINTMENT','CHAPTER I. STATUTE AND APPOINTMENT','',''),(169,'Articles','Article 146','Article 146. Definition','The President of the Republic is the Head of State, embodying national unity, representing the nation on a national and an international scale, and overseeing the correct functioning of the State offices.\nThe Head of State shall be the guarantor of the Constitution.\nThe Head of State shall be the Head of Government.\nThe President of the Republic shall be the Commander-in-Chief of the Defence and Security Forces.',''),(170,'Articles','Article 147','Article 147. Eligibility','The President of the Republic shall be elected through direct, universal, equal and periodic suffrage and by personal and secret ballot.\nAll Mozambican citizens may be candidates for the office of President of the Republic, provided that they meet all of the following conditions:\nthat they possess nationality by origin and do not possess any other nationality;\nthat they are at least thirty-five years of age;\nthat they are in full possession of their civil and political rights;\nthat they have been proposed by at least ten thousand voters.\nThe term of the office of the President of the Republic shall be five years.\nThe President of the Republic may be re-elected only once.\nA President of the Republic who has been elected on two consecutive occasions may be a candidate for further presidential elections only five years after the end of his last term of office.',''),(171,'Articles','Article 148','Article 148. Election','The candidate who gains more than half of the votes cast shall be elected President of the Republic.\nIf none of the candidates obtains an absolute majority, there shall be a second round between the two candidates receiving the most votes.',''),(172,'Articles','Article 149','Article 149. Incompatibility','The President of the Republic may not, except where the Constitution expressly provides otherwise, perform any other public function, and in no event may he perform any private functions.',''),(173,'Articles','Article 150','Article 150. Investiture and Swearing Into Office','The President of the Republic shall be sworn into office by the President of the Constitutional Council in a public ceremony before the deputies of the Assembly of the Republic and other representatives of the sovereign public offices.\nOn assuming office, the President of the Republic shall take the following oath:\nI do swear on my honour that I will respect and ensure respect for the Constitution, that I will faithfully carry out the task of President of the Republic of Mozambique, that I will dedicate all my efforts to the defence, promotion and consolidation of national unity, to human rights, to democracy and to the well-being of the Mozambican people, and I will ensure that justice is done for all citizens.',''),(174,'Articles','Article 151','Article 151. Disability or Absence','In the event of short-term disability or absence of the President of the Republic from the country, he shall be substituted by the President of the Assembly of the Republic or, in his absence, by his substitute.\nThe simultaneous absence from the country of the Head of State and his constitutional substitute shall be prohibited.\nThe Assembly of the Republic, the Constitutional Council and the Government shall be notified immediately of any short-term disability or absence of the President of the Republic.',''),(175,'Articles','Article 152','Article 152. Interim Substitute and Incompatibilities','The President of the Assembly of the Republic shall also assume the functions of the Head of State on an interim basis in the following circumstances:\nin the event of death or permanent incapacitation, certified by a medical board;\nin the event of resignation, notified to the Assembly of the Republic;\nin the event of suspension or dismissal as a result of an indictment or conviction by the Supreme Court.\nThe circumstances referred to in the preceding paragraph shall result in the holding of presidential elections.\nIf the President of the Republic resigns from office, he may not run as a candidate for a new term of office for the next ten years.\nWhile the President of the Assembly of the Republic is acting as interim President of the Republic, his functions as a deputy shall be suspended automatically.',''),(176,'Articles','Article 153','Article 153. Criminal Responsibility','For crimes committed in the performance of his functions, the President of the Republic shall be tried before the Supreme Court.\nFor crimes committed outside the performance of his functions, the President of the Republic shall be tried before the ordinary courts, at the end of his term of office.\nIt shall be incumbent upon the Assembly of the Republic to request that the Attorney General of the Republic institute criminal proceedings against the President of the Republic, upon the recommendation of at least one third and carried by a majority of two thirds of the deputies of the Assembly of the Republic.\nThe President of the Republic shall be suspended from his duties as of the date on which definitive indictment or its equivalent has been passed, and his conviction shall result in his discharge from office.\nThe Supreme Court, sitting in plenary session, shall deliver its judgement within a maximum period of sixty days.\nIn the event of a conviction, the President of the Republic shall not be able to stand as a candidate for that office again, nor may he hold any position in a sovereign public office or a local authority.',''),(177,'Articles','Article 154','Article 154. Preventive Detention','In no circumstances whatsoever shall the President of the Republic in office be subjected to preventive detention.',''),(178,'Articles','Article 155','Article 155. Election in the Event of Vacancy of Office','The election of a new President of the Republic in the event of death, permanent incapacitation, resignation or discharge, shall take place within the following ninety days, and the interim President of the Republic shall be barred from standing as a candidate.\nAn election for the office of President of the Republic shall not be held if the vacancy occurs during the three hundred and sixty five days preceding the end of the term of office, in which case the interim President of the Republic shall hold office until the next general election.',''),(179,'Articles','Article 156','Article 156. Incapacitation','The permanent incapacitation of the President of the Republic shall be certified by a medical board, as defined by the law.\nThe permanent incapacitation of the President of the Republic shall be declared by the Constitutional Council.\nThe Constitutional Council shall certify the death and the divestiture of office of the President of the Republic.',''),(180,'Articles','Article 157','Article 157. Regime Governing the Interim Period','During the period in which the office of President of the Republic is vacant, the Constitution may not be altered.\nThe interim President of the Republic shall guarantee the functioning of the offices of the State and all other institutions, but shall not exercise the powers referred to in article 159 paragraphs (c), (e), (f), (g), (h) (i) and (j), article 160 paragraphs 1(b) and 1(c), article 161 paragraph 2(e) and article 162 (c).',''),(181,'Articles','Article 158','Article 158. Form of Acts','Normative acts of the President of the Republic shall take the form of presidential decrees, and other decisions shall take the form of presidential orders, and they shall be published in the Boletim da República.',''),(182,'Structure','CHAPTER II. POWERS','CHAPTER II. POWERS','',''),(183,'Articles','Article 159','Article 159. General Powers','In the performance of his functions, the Head of State shall have the power to:\naddress the nation through messages and communications;\ninform the Assembly of the Republic every year on the general state of the Nation;\ndecide, in the terms of article 136, to call referenda on issues of major national interest;\ncall a general election;\ndissolve the Assembly of the Republic in terms of article 188;\ndismiss all other members of Government when its programme has been rejected by the Assembly of the Republic for the second time;\nappoint the President of the Supreme Court, the President of the Constitutional Council, the President of the Administrative Court and the Vice President of the Supreme Court;\nappoint, exonerate and dismiss the Attorney General of the Republic and the Deputy Attorney General of the Republic;\ngrant pardons and commute sentences;\nconfer, within the terms of the law, honorary titles, decorations and distinctions.',''),(184,'Articles','Article 160','Article 160. In Matters of Government','In matters of Government activity, the President of the Republic shall have power to:\nconvene and preside at sessions of the Council of Ministers;\nappoint, exonerate and dismiss the Prime Minister;\ncreate ministries and ministerial commissions.\nIn addition, he shall have power to appoint, exonerate and dismiss:\nthe Ministers and Deputy-Ministers;\nthe Provincial Governors;\nthe Principals and Vice-Principals of State universities, on the recommendation of the respective management boards, in accordance with the law;\nthe Governor and Vice-Governor of the Bank of Mozambique;\nthe Secretaries of State.',''),(185,'Articles','Article 161','Article 161. In Matters of Defence and Public Order','In matters of national defence and of public order, the President of the Republic shall have power to:\ndeclare a state of war and its termination, a state of siege, or a state of emergency;\nsign treaties;\ndecree general or partial mobilisation;\npreside over the National Council of Defence and Security;\nappoint, exonerate and dismiss the Chief and Deputy Chief of the General Staff, the General Commander and Deputy General Commander of the Police, the Wing Commanders of the Armed Forces of Mozambique, and other officers of the Defence and Security Forces in the terms established by law.',''),(186,'Articles','Article 162','Article 162. In Matters of International Relations','In matters of international relations, the President of the Republic shall have power to:\nguide foreign policy;\nenter into international treaties;\nappoint, exonerate and dismiss ambassadors and diplomatic envoys of the Republic of Mozambique;\nreceive the credentials of ambassadors and diplomatic envoys of other countries.',''),(187,'Articles','Article 163','Article 163. Enactment and Veto','The President of the Republic shall have the power to enact laws and to order their publication in the Boletim da República.\nBills shall be enacted into law within thirty days after being received or after notification of the decision delivered by the Constitutional Council that none of the provisions of the bill are unconstitutional.\nThe President of the Republic may, by order with reasons adduced, veto a bill and return it to the Assembly of the Republic for re-examination.\nShould the bill, on re-examination, be approved by a two-thirds majority of the Assembly of the Republic, the President of the Republic must enact it into law and order its publication.',''),(188,'Structure','CHAPTER III. COUNCIL OF STATE','CHAPTER III. COUNCIL OF STATE','',''),(189,'Articles','Article 164','Article 164. Definition and Composition','The Council of State is a political body to advise the President of the Republic.\nThe Council of State shall be presided over by the President of the Republic and it shall have the following composition:\nthe President of the Assembly of the Republic;\nthe Prime Minister;\nthe President of the Constitutional Council;\nthe Ombudsman;\nthe former Presidents of the Republic who were not dismissed from office;\nthe former Presidents of the Assembly of the Republic;\nseven persons of recognised merit elected by the Assembly of the Republic, for the length of the legislative term, on the basis of parliamentary  representation;\nfour persons of recognised merit appointed by the President of the Republic, for the term of his office;\nthe runner-up of the Presidential elections.',''),(190,'Articles','Article 165','Article 165. Taking Office and Status','The members of the Council of State shall take up office before the President of the Republic.\nThe members of the Council of State shall continue to perform their functions while they remain in their respective offices.\nThe members of the Council of State shall enjoy such privileges, immunities and ceremonial treatment as the law may establish.',''),(191,'Articles','Article 166','Article 166. Powers','The Council of State shall, in general, advise the President of the Republic on the performance of his functions whenever the President requests such advice, and it must, compulsorily, pronounce itself on:\nthe dissolution of the Assembly of the Republic;\nthe declaration of a state of war, a state of siege or a state of emergency;\nthe holding of referenda, in the terms of article 159 (c)\nthe calling of a general election.',''),(192,'Articles','Article 167','Article 167. Functioning','The opinions of the Council of State shall be issued at a meeting convened for this purpose and presided over by the President of the Republic, and may be made public when the action to which they refer is carried out.\nMeetings of the Council of State shall not be public.\nThe Council of State shall establish its own bylaws.',''),(193,'Structure','TITLE VII. ASSEMBLY OF THE REPUBLIC','TITLE VII. ASSEMBLY OF THE REPUBLIC','',''),(194,'Structure','CHAPTER I. STATUS AND ELECTION','CHAPTER I. STATUS AND ELECTION','',''),(195,'Articles','Article 168','Article 168. Definition','The Assembly of the Republic is the representative assembly of all Mozambican citizens.\nDeputies shall represent the entire country and not only the area by which they were elected.',''),(196,'Articles','Article 169','Article 169. Functions','The Assembly of the Republic is the highest legislative body in the Republic of Mozambique.\nThe Assembly of the Republic determines the norms that conduct the functioning of the State and the economic and social life through laws and deliberations of generic character.',''),(197,'Articles','Article 170','Article 170. Election and Composition','The Assembly of the Republic shall be elected through direct, universal, equal and periodic suffrage and by secret and personal ballot.\nThe Assembly of the Republic shall consist of two hundred and fifty deputies.\nCandidates for election shall be political parties, either individually or in coalitions, and their respective lists may include citizens who are not party members.',''),(198,'Articles','Article 171','Article 171. Term of Office of Deputies','The term of office of the deputies shall be the same as the legislative term, except in the event of resignation or loss of office.\nThe suspension, substitution, resignation or loss of office of deputies shall be regulated by the Statute of Deputies.',''),(199,'Articles','Article 172','Article 172. Incompatibility','The office of deputy shall be incompatible with the following offices:\nmember of Government;\njudicial officer in office;\ndiplomat in active service;\nmilitary and police officers in active service;\nprovincial governor and district administrator;\nholders of offices in local authorities.\nThe law shall establish any other incompatibilities.',''),(200,'Articles','Article 173','Article 173. Powers of Deputies','The deputies shall have the following powers:\nto exercise the right to vote;\nto present bills and proposals for resolutions and other decisions;\nto stand as candidates for offices of the Assembly of the Republic;\nto request and obtain from the Government or from public institutions such data and information as are required for the performance of their functions;\nto put questions to the Government;\nother powers assigned by the Bylaws of the Assembly of the Republic.',''),(201,'Articles','Article 174','Article 174. Immunities','No deputy may be arrested or detained except in the event of flagrante delicto, or put on trial without the consent of the Assembly of the Republic.\nIf criminal proceedings are pending in which a deputy is the accused, the deputy shall be heard by a judge of appeal.\nDeputies shall enjoy a special forum and shall be tried by the Supreme Court in terms of the law.',''),(202,'Articles','Article 175','Article 175. Non-Liability','The deputies of the Assembly of the Republic may not be sued, detained or put on trial for the opinions voiced or votes cast in exercising their functions as deputies.\nThe above does not apply to civil or criminal liability for libel, defamation or slander.',''),(203,'Articles','Article 176','Article 176. Rights and Privileges of Deputies','Deputies shall enjoy the following rights and other privileges:\nA special identification card;\nfree movement through public places with restricted access, when in the performance or because of their functions;\nsupport, co-operation, protection and facilities from public or military entities of the Republic, for the purposes of the performance of their functions within the terms of the law;\nremuneration and subsidies established by law.\nDeputies may not take part in judicial proceedings as witnesses or expert witnesses, unless this has been authorised by the Assembly of the Republic or by its Standing Commission.\nDeputies shall also enjoy the other rights and privileges established by law.',''),(204,'Articles','Article 177','Article 177. Duties of Deputies','Deputies shall have the following duties:\nto comply with the Constitution and the laws;\nto comply with the Statute of Deputies;\nto respect the dignity of the Assembly of the Republic and its deputies;\nto attend plenary sessions and sessions of the commission of which he is a  member;\nto take part in voting and in the work of the Assembly of the Republic.',''),(205,'Articles','Article 178','Article 178. Resignation and Loss of Office','A deputy may resign from office within the terms of the law.\nDeputies shall lose their office if they:\nhave been definitively convicted of a felonious crime that carries a prison sentence of over two years;\nbecome a member of or take on functions in a party or coalition other than the one for which they were elected;\ndo not take up a seat in the Assembly of the Republic, or exceed the number of absences established in the Bylaws.\nLoss of office shall also occur in the event of any ineligibility existing at the date of the elections and discovered subsequently, as well as any form of incapacity prescribed by law.',''),(206,'Structure','CHAPTER II. POWERS','CHAPTER II. POWERS','',''),(207,'Articles','Article 179','Article 179. Powers','The Assembly of the Republic shall have power to legislate on basic issues of the country’s domestic and foreign policy.\nThe Assembly of the Republic shall have exclusive power to:\npass constitutional laws;\ndelimit the boundaries of the Republic of Mozambique;\ndecide on territorial divisions;\napprove the electoral law and the rules for referenda;\napprove and terminate treaties dealing with issues within their jurisdiction;\npropose the holding of referenda on matters of national interest;\nendorse the suspension of constitutional guarantees and the declaration of state of siege or a state of emergency;\nratify the appointment of the President of the Supreme Court, the President of the Constitutional Council, the President of the Administrative Court and the Vice President of the Supreme Court;\nelect the Ombudsman;\ndecide on the Government programme;\ndecide on reports on the activities of the Council of Ministers;\ndecide on the major options of the Economic and Social Plan and the State Budget and the respective reports on their implementation;\napprove the State Budget;\ndefine defence and security policy, after consulting the National Defence and Security Council;\ndefine the bases for tax policy and the tax system;\nauthorise the Government, while defining the general conditions, to contract and make loans and to carry out other credit transactions, for periods exceeding one financial year, and to establish the upper limit for guarantees that may be given by the State;\ndefine the statute for holders of sovereign public offices, holders of provincial offices and holders of offices in local authorities;\ndecide on the general bases for the organisation and functioning of Public Administration;\nratify decree-laws;\nratify and terminate international treaties;\nratify treaties on Mozambique’s participation in international defence organisations;\ngrant amnesties and pardons.\nWith the exception of those powers stated in paragraph 2 of this article, the Assembly of the Republic may authorise the Government to legislate on other matters in the form of decree-laws.\nThe Assembly of the Republic shall also have power to:\nelect the President, the Vice Presidents and the Standing Commission;\napprove the Bylaws of the Assembly of the Republic and the Statute of Deputies;\nset up Commissions of the Assembly of the Republic and regulate their operation;\ncreate national parliamentary groups.',''),(208,'Articles','Article 180','Article 180. Laws Delegating Legislative Authority','Laws delegating legislative authority shall define the purpose, intention, extent and duration of the authority.\nLegislative authority may not be used more than once, without prejudice to cases where its implementation is broken down into parts or where it has been extended.\nLegislative authority shall expire at the end of the legislative term or on the dissolution of the Assembly of the Republic.\nThe Government shall publish authorised legislative acts by the last day of the time limit stipulated in the authorising legislation, which shall commence on the date of its publication.',''),(209,'Articles','Article 181','Article 181. Decree-Laws','A decree-law passed by the Council of Ministers under the authority of authorising legislation shall be deemed ratified if its ratification is not demanded by a minimum of fifteen deputies during the session of the Assembly of the Republic held immediately after its publication.\nThe Assembly of the Republic may wholly or partially suspend the legal force of a decree-law until it has been evaluated.\nThe suspension shall expire if by the end of the session the Assembly has not pronounced on the matter.\nRefusal to ratify shall result in revocation.',''),(210,'Articles','Article 182','Article 182. Form of Acts','Legislative acts of the Assembly of the Republic shall take the form of laws, and its other decisions shall take the form of resolutions, and they shall be published in the Boletim da República.',''),(211,'Articles','Article 183','Article 183. Legislative Initiative','Legislative initiative shall belong to:\nthe deputies;\nthe parliamentary benches;\nthe commissions of the Assembly of the Republic;\nthe President of the Republic;\nthe Government.\nThe deputies and the parliamentary benches may not propose bills which, directly or indirectly, involve an increase in State expenditure or a reduction in State revenue, or which in any way change the financial year in progress.',''),(212,'Articles','Article 184','Article 184. Rules for Debate and Voting','Debate of legislative proposals and bills, and of proposed referenda, shall consist of a general first reading and a specialised second reading.\nVoting shall consist of a vote on the first reading, a vote on the second reading and a final overall vote.\nIf the Assembly so resolves, texts approved on the first reading shall be put to the commissions for a vote on the second reading, without prejudice to the power of the Assembly to recall them and put them to a final plenary vote for overall approval.',''),(213,'Structure','CHAPTER III. ORGANISATION AND FUNCTIONING','CHAPTER III. ORGANISATION AND FUNCTIONING','',''),(214,'Articles','Article 185','Article 185. Legislative Term','The legislative term shall be of five years and it shall commence with the first session of the Assembly of the Republic held after the elections and terminate with the first session of the newly elected Assembly.\nThe first session of the Assembly of the Republic shall take place within twenty days after the election results have been announced and validated.',''),(215,'Articles','Article 186','Article 186. Parliamentary Sessions','The Assembly of the Republic shall meet in ordinary session twice each year, and in extraordinary session whenever requested by the President of the Republic, by the Standing Commission or by at least one third of the deputies.',''),(216,'Articles','Article 187','Article 187. Quorum and Decision Making','The Assembly of the Republic may deliberate and make decisions only when more than half of its deputies are present.\nDecisions of the Assembly of the Republic shall be carried by more than half of the votes of the deputies present.\nMatters relating to the statute of the opposition shall be carried by a majority of two thirds of the votes of the deputies.',''),(217,'Articles','Article 188','Article 188. Dissolution','The President of the Republic may dissolve the Assembly of the Republic if it rejects the Government programme, after debate.\nThe President of the Republic shall call new legislative elections, in the terms of the Constitution.',''),(218,'Articles','Article 189','Article 189. Restrictions on Dissolution','The Assembly of the Republic may not be dissolved in the event of a state of siege or a state of emergency, during the course of such a state, or until sixty days after it has terminated.\nA dissolution carried out contrary to the provisions of the preceding paragraph shall be of no legal effect whatsoever.\nThe dissolution of the Assembly of the Republic shall not bring to an end the term of office of its deputies nor the powers and functions of the Standing Commission, which shall subsist until the first session of the new elected Assembly.\nIn the event of dissolution, the new Assembly shall begin a new legislative term, which shall endure for the remainder of the previous legislative term.',''),(219,'Articles','Article 190','Article 190. President of the Assembly of the Republic','The Assembly of the Republic shall elect from among its members a President of the Assembly of the Republic.\nThe Head of State shall convene and chair the session at which the election of the President of the Assembly of the Republic takes place.\nThe President of the Assembly of the Republic shall be sworn into office by the President of the Constitutional Council.\nThe President of the Assembly of the Republic is answerable to the Assembly of the Republic.',''),(220,'Articles','Article 191','Article 191. Powers of the President of the Assembly of the Republic','The President of the Assembly of the Republic shall have power to:\nconvene and chair sessions of the Assembly of the Republic and of its Standing Commission;\nensure compliance with the decisions of the Assembly of the Republic;\nsign laws of the Assembly of the Republic and submit them for enactment;\nsign and order the publication of resolutions of the Assembly of the Republic;\nrepresent the Assembly of the Republic on a domestic and international level;\npromote institutional relations between the Assembly of the Republic and the Provincial Assemblies, in accordance with the rules in their bylaws;\nexercise any other powers established by the Constitution and the Bylaws;',''),(221,'Articles','Article 192','Article 192. Vice Presidents of the Assembly of the Republic','The Assembly of the Republic shall elect from among its members Vice Presidents nominated by the parties with the greatest parliamentary representation.\nIn the case of absence or disability of the President of the Assembly of the Republic, his functions shall be exercised by the Vice Presidents.',''),(222,'Articles','Article 193','Article 193. Standing Commission','The Standing Commission is the body of the Assembly of the Republic that coordinates the activities of the Assembly in plenary sitting and of its commissions and national parliamentary groups.\nThe Standing Commission of the Assembly of the Republic shall be composed of the President, the Vice Presidents and other deputies elected in the terms of the law, on the recommendation of the parliamentary benches, according to their degree of representation.\nThe representatives referred to in the preceding paragraphs shall have the same number of votes in the Standing Commission as that of the benches that they represent.\nThe Standing Commission of the Assembly of the Republic shall sit during the intermissions of the plenary sessions, and at other times established in the Constitution and the law.',''),(223,'Articles','Article 194','Article 194. Permanence','At the end of the legislative term or in the event of dissolution, the Standing Commission of the Assembly of the Republic shall remain in office until the founding session of the newly elected Assembly.',''),(224,'Articles','Article 195','Article 195. Powers','The Standing Commission of the Assembly of the Republic shall have power to:\nexercise the powers of the Assembly of the Republic with respect to the terms of office of the deputies;\nensure compliance with the Constitution and the laws, and monitor the activity of the Government and the Public Administration;\ngive its prior opinion on the declaration of war;\nauthorise or confirm, subject to ratification, declarations of states of siege and states of emergency, whenever the Assembly of the Republic is not in session;\nconduct the relations between the Assembly of the Republic and parliaments and similar institutions in other countries;\nauthorise the President of the Republic to make State visits abroad;\nestablish commissions of inquiry of an urgent nature, during intermissions between plenary sessions of the Assembly of the Republic;\nprepare and organise sessions of the Assembly of the Republic;\nexercise such other functions as are conferred by the Bylaws of the Assembly of the Republic;\nconduct the work of the plenary sessions;\nannounce the loss of office and resignation of deputies, as well as suspensions, in terms of the Constitution and the Bylaws of the Assembly of the Republic;\ndecide on questions of interpretation of the Bylaws of the Assembly of the Republic during intermissions between plenary sessions;\nintegrate the initiatives of deputies, the benches or the Government in the work of each session;\nsupport the President of the Assembly of the Republic in the administrative and financial management of the Assembly.',''),(225,'Articles','Article 196','Article 196. Parliamentary Benches','The deputies elected by each political party may set up a parliamentary bench.\nThe formation and organisation of benches shall be provided for in the Bylaws of the Assembly of the Republic.',''),(226,'Articles','Article 197','Article 197. Powers of the Parliamentary Benches','The Parliamentary Benches shall have the following powers:\nto present candidates for the office of President of the Assembly of the Republic;\nto propose candidates for Vice President of the Assembly of the Republic;\nto nominate candidates for the Standing Commission of the Assembly of the Republic;\nto nominate candidates for commissions of the Assembly of the Republic;\nto exercise legislative initiative;\nto call for debate on current and urgent issues of national interest, with the presence of the Government;\nto call for the formation of parliamentary commissions of inquiry;\nto call for debate on urgent issues that are not on the agenda;\nto request information from and put questions to the Government.\nEach parliamentary bench shall be entitled to have access to places of work within the Assembly of the Republic, as well as to technical and administrative staff, in terms of the law.',''),(227,'Articles','Article 198','Article 198. Government Five-Year Programme','At the beginning of the legislative term, the Assembly of the Republic shall evaluate the Government programme.\nThe Government may present a revised programme that takes into account the outcomes of the debate.',''),(228,'Articles','Article 199','Article 199. Participation of Members of Government in the Sessions','The Prime Minister and the Ministers shall be entitled to attend the plenary sessions of the Assembly of the Republic, and shall have the right to speak, in accordance with the Bylaws.\nAt plenary sessions of the Assembly of the Republic, the attendance of the member or members of Government that have been summoned shall be mandatory.',''),(229,'Structure','TITLE VIII. GOVERNMENT','TITLE VIII. GOVERNMENT','',''),(230,'Structure','CHAPTER I. DEFINITION AND COMPOSITION','CHAPTER I. DEFINITION AND COMPOSITION','',''),(231,'Articles','Article 200','Article 200. Definition','The Government of the Republic of Mozambique is the Council of Ministers.',''),(232,'Articles','Article 201','Article 201. Composition','The Council of Ministers shall consist of the President of the Republic, who shall preside, the Prime Minister and the Ministers.\nDeputy Ministers and Secretaries of State may be summoned to take part in meetings of the Council of Ministers.',''),(233,'Articles','Article 202','Article 202. Convocation and Chairmanship','In discharging its functions, the Council of Ministers shall do so in accordance with the decisions of the President of the Republic and of the Assembly of the Republic.\nThe Council of Ministers shall be convened and chaired by the Prime Minister, to whom this power is delegated by the President of the Republic.\nGovernment policies shall be formulated by the Council of Ministers in sessions led by the President of the Republic.',''),(234,'Structure','CHAPTER II. POWERS AND RESPONSIBILITIES','CHAPTER II. POWERS AND RESPONSIBILITIES','',''),(235,'Articles','Article 203','Article 203. Functions','The Council of Ministers shall secure the administration of the country, shall guarantee its territorial integrity, shall safeguard public order and the security and stability of citizens, shall promote economic development, shall implement the State’s social agenda, shall develop and consolidate legality and shall carry out the country’s foreign policy.\nThe defence of public order shall be guaranteed by the appropriate entities operating under government control.',''),(236,'Articles','Article 204','Article 204. Powers','In particular, the Council of Ministers shall have the power to:\nguarantee the enjoyment by citizens of their rights and freedoms;\nsecure public order and social discipline;\ndraft bills to be submitted to the Assembly of the Republic;\npass decree-laws under the legislative authority of the Assembly of the Republic;\nprepare the Economic and Social Plan and the State Budget and implement them after they have been approved by the Assembly of the Republic;\npromote and regulate economic activity and the activity of social sectors;\nprepare the signature of international treaties and sign, ratify, adhere to and terminate international agreements, in matters that are within their governmental jurisdiction;\ndirect labour and social security policy;\ndirect the State sectors, particularly education and health;\ndirect and promote housing policy.\nThe Council of Ministers shall also have power to:\nguarantee the defence and consolidation of the public domain and property of the State;\ndirect and co-ordinate the activities of the ministries and other offices subordinate to the Council of Ministers;\nevaluate the experiences of local executive offices and regulate their organisation and functioning, and supervise the offices of the local authorities within the terms of the law;\nencourage and support entrepreneurial activity and the exercise of private initiative, and protect the interests of consumers and of the general public;\npromote the development of co-operatives and support family sector production.\nThe Government shall have exclusive legislative initiative in respect of matters concerning its own organisation, composition and functioning.',''),(237,'Articles','Article 205','Article 205. Powers of the Prime Minister','Without prejudice to other attributes conferred upon him by the President of the Republic and by law, the Prime Minister shall assist and advise the President of the Republic in the running of Government.\nIn particular, the Prime Minister shall have power to:\nassist the President of the Republic in drawing up the Government Programme;\nadvise the President of the Republic on the creation of ministries and ministerial commissions, and on the appointment of members of the Government and  other governmental heads;\ndraft the Government’s plan of work and present it to the President of the Republic;\nensure that members of the Government implement decisions taken by State offices;\nchair the meetings of the Council of Ministers dealing with the implementation of defined policies and other decisions;\nco-ordinate and control the activities of ministries and other governmental institutions;\nsupervise the technical and administrative operations of the Council of Ministers.',''),(238,'Articles','Article 206','Article 206. Relationship with the Assembly of the Republic','In his relations with the Assembly of the Republic, the Prime Minister shall have power to:\npresent to the Assembly of the Republic the Government’s programme, the draft Economic and Social Plan and the draft State Budget;\npresent Government implementation reports;\nexpress the Government’s positions to the Assembly of the Republic.\nIn the exercise of these functions, the Prime Minister shall be assisted by members of the Council of Ministers, whom he shall have designated.',''),(239,'Articles','Article 207','Article 207. Accountability of the Council of Ministers','The Council of Ministers shall be answerable to the President of the Republic and to the Assembly of the Republic on the implementation of domestic and foreign policy, and shall be accountable to them for its actions in the terms of the law.',''),(240,'Articles','Article 208','Article 208. Political Accountability of Members of Government','The members of the Council of Ministers shall be accountable to the President of the Republic and to the Prime Minister for the enforcement of the decisions of the Council of Ministers within their areas of jurisdiction.',''),(241,'Articles','Article 209','Article 209. Collective Responsibility','The members of the Government shall be bound by the Government Programme and by the decisions of the Council of Ministers.',''),(242,'Articles','Article 210','Article 210. Form of Acts','Normative acts of the Council of Ministers shall take the form of decree-laws and decrees.\nThe decree-laws and decrees referred to in the preceding paragraph shall indicate the law under the authority of which they were passed.\nThe President of the Republic shall sign and order the publication of decree- laws, and the Prime Minister shall sign and order the publication of other decrees of the Government.\nAll other Government acts shall take the form of resolutions.',''),(243,'Articles','Article 211','Article 211. Immunities','No member of Government may be arrested or detained without the permission of the President of the Republic, unless apprehended in the act of committing a felonious crime that carries a sentence of long-term imprisonment.\nIn the event that criminal proceedings are brought against a member of Government, and the member has been definitively charged, the President of the Republic shall decide whether or not the member should be suspended for the purposes of the proceedings, and a decision to suspend shall be mandatory when the crime in question is of the type referred to in the preceding paragraph.',''),(244,'Structure','TITLE IX. COURTS','TITLE IX. COURTS','',''),(245,'Structure','CHAPTER I. GENERAL PRINCIPLES','CHAPTER I. GENERAL PRINCIPLES','',''),(246,'Articles','Article 212','Article 212. Jurisdictional Function','It shall be the function of the courts to guarantee and strengthen the rule of law as an instrument of legal stability, to guarantee respect for the laws, to safeguard the rights and freedoms of citizens, as well as the vested interests of other bodies and entities that have legal existence.\nThe courts shall punish violations of the legal order and shall adjudicate cases in accordance with the law.\nThe law may establish institutional and procedural mechanisms for links between courts and other forums whose purpose is the settlement of interests and the resolution of disputes.',''),(247,'Articles','Article 213','Article 213. Educational Function','The courts shall educate citizens and the public administration in the voluntary and conscientious observance of laws, thereby establishing a just and harmonious social community.',''),(248,'Articles','Article 214','Article 214. Unconstitutionality','In matters brought before them for decision, the courts shall not apply laws or principles that are contrary to the Constitution.',''),(249,'Articles','Article 215','Article 215. Court Decisions','Court decisions shall be binding on all citizens and other legal persons, and these decisions shall take precedence over the decisions of other authorities.',''),(250,'Articles','Article 216','Article 216. Participation of Elected Magistrates','Elected magistrates may take part in trials, in the terms of the law.\nElected magistrates shall only take part in first instance judgements and in decisions on questions of fact.\nParticipation of elected magistrates shall be compulsory in cases where the procedural law requires it, or when the trial judge so decides, when the Public Prosecution Service recommends it or when the parties request it.\nThe law shall establish the manner in which the magistrates referred to in this article are elected, as well as the duration of their terms of office.',''),(251,'Structure','CHAPTER II. STATUTE OF JUDGES','CHAPTER II. STATUTE OF JUDGES','',''),(252,'Articles','Article 217','Article 217. Independence of Judges','In the exercise of their functions, judges shall be independent and shall owe obedience only to the law.\nJudges shall likewise be impartial and unaccountable.\nJudges shall be irremovable, inasmuch as they cannot be transferred, suspended, retired or dismissed, except in the cases established by law.',''),(253,'Articles','Article 218','Article 218. Responsibility','Judges may be held responsible in civil, criminal and disciplinary proceedings for acts committed in the discharge of their duties only in cases specified by law.\nThe removal of a professional judge from the bench may take place only under legally established terms.',''),(254,'Articles','Article 219','Article 219. Incompatibility','Judges in office may not undertake any other public or private activity, except for teaching, legal research or other activities of scientific, literary, artistic and technical dissemination or publication, with prior authorisation from the Superior Council of the Judiciary.',''),(255,'Articles','Article 220','Article 220. Superior Council of the Judiciary','The Superior Council of the Judiciary shall be the body responsible for the management and discipline of the judiciary.',''),(256,'Articles','Article 221','Article 221. Composition','The Superior Council of the Judiciary shall be composed of:\nthe President of the Supreme Court;\nthe Vice President of the Supreme Court;\ntwo members appointed by the President of the Republic;\nfive members elected by the Assembly of the Republic, according to principles of proportional representation;\nseven members of the judiciary in different categories, all of whom shall be elected by their peers in the terms of the Statute of Judges.\nThe Superior Council of the Judiciary shall be presided over by the President of the Supreme Court, who shall be substituted, in cases of absence or disability, by the Vice President of the Supreme Court.\nThe Superior Council of the Judiciary shall incorporate officers of justice elected by their peers for discussion and deliberation on matters related to professional merit and to the exercise disciplinary authority over them, in terms to be established by law.\nThe law shall regulate all other matters in respect of the powers, organization and functioning of the Superior Council of the Judiciary.',''),(257,'Articles','Article 222','Article 222. Powers','The Superior Council of the Judiciary shall have power to:\nnominate, appoint, transfer, promote, exonerate and evaluate professional merit, take disciplinary action and, in general, carry out all acts of the same nature in relation to members of the judiciary;\nevaluate professional merit and take disciplinary action in relation to officers of justice, without prejudice to the disciplinary powers assigned to judges;\npropose extraordinary inspections, inquiries and investigations to the courts;\ngive opinions and make recommendations on the policy of the judiciary, on its own initiative or at the request of the President of the Republic, the President of the Assembly of the Republic or the Government.',''),(258,'Structure','CHAPTER III. ORGANISATION OF THE COURTS','CHAPTER III. ORGANISATION OF THE COURTS','',''),(259,'Structure','SECTION I. CATEGORIES OR COURTS','SECTION I. CATEGORIES OR COURTS','',''),(260,'Articles','Article 223','Article 223. Categories of Courts','In the Republic of Mozambique, there shall be the following courts:\nthe Supreme Court;\nthe Administrative Court;\nthe courts of justice.\nThere may be administrative courts, labour courts, fiscal courts, customs courts, admiralty courts, arbitration courts and community courts.\nThe powers, organisation and functioning of the courts referred to in the preceding paragraph shall be established by law, which may provide for a hierarchical order among courts from provincial courts to the Supreme Court.\nThe courts of justice shall have common jurisdiction in civil and criminal matters and shall exercise their jurisdiction over all areas not assigned to other jurisdictional orders.\nAt first instance, there may be courts of special jurisdiction and specialized courts to adjudicate particular matters.\nThe establishment of courts with exclusive jurisdiction to try specific categories of crimes shall not be permitted, subject to the provisions on courts martial.',''),(261,'Articles','Article 224','Article 224. Courts Martial','Courts martial with jurisdiction to try crimes of a strictly military nature shall be established during times of war.',''),(262,'Structure','SECTION II. SUPREME COURT','SECTION II. SUPREME COURT','',''),(263,'Articles','Article 225','Article 225. Definition','The Supreme Court shall be the highest body within the hierarchy of courts of justice.\nThe Supreme Court shall ensure the uniform application of the law within its sphere of jurisdiction, in the interests of the Mozambican people.',''),(264,'Articles','Article 226','Article 226. Composition','The Supreme Court shall be composed of judges of appeal, whose number shall be established by law.\nThe President of the Republic shall nominate the President and the Vice President of the Supreme Court, after consultation with the Superior Council of the Judiciary.\nJudges of the Supreme Court shall be nominated by the President of the Republic on the recommendation of the Superior Council of the Judiciary, on the basis of their curricula, after a public tender open to judges and other national citizens of reputed merit, all of whom shall hold degrees in law and be in full possession of their civil and political rights.\nAt the time of their appointment, judges of the Supreme Court shall be of at least thirty-five years of age and shall have at least ten years of experience at the bar or in teaching law, and all other requirements shall be fixed by law.',''),(265,'Articles','Article 227','Article 227. Functioning','The Supreme Court shall sit:\nin divisions, as a court of first instance and as a court of appeal;\nin plenary session, sitting either as a court of appeal or as a court of sole instance, in cases expressly provided for in the law.',''),(266,'Structure','SECTION III. ADMINISTRATIVE COURT','SECTION III. ADMINISTRATIVE COURT','',''),(267,'Articles','Article 228','Article 228. Definition','The Administrative Court shall be the highest body in the hierarchy of administrative, customs and fiscal courts.\nThe Administrative Court shall control the legality of administrative acts and the application of rules and regulations issued by the Public Administration, and it shall scrutinise the legality of public expenditure and the enforcement of liability for financial infractions.',''),(268,'Articles','Article 229','Article 229. Composition','The Administrative Court shall be composed of judges of appeal, whose number shall be established by law.\nThe President of the Republic shall nominate the President of the Administrative Court, after consultation with the Superior Council of the Administrative Judiciary.\nJudges of the Administrative Court shall be nominated by the President of the Republic on the recommendation of the Superior Council of the Administrative Judiciary.\nAt the time of their appointment, judges of the Administrative Court shall be of at least thirty-five years of age and shall meet all other requirements established by law.',''),(269,'Articles','Article 230','Article 230. Powers','In particular, the Administrative Court shall:\nadjudicate cases concerning disputes arising from administrative legal relations;\nadjudicate appeals lodged against decisions of State offices and of their office holders and agents;\nhear appeals lodged against judgements delivered by administrative, fiscal and customs courts.\nThe Administrative Court shall also:\nissue a report and opinion on the General State Account;\ncarry out prior scrutiny of the legality of, and budget cover for, acts and contracts that are subject to Administrative Court jurisdiction;\nscrutinise public moneys successively and concomitantly;\nsupervise the use of financial resources obtained abroad, namely, through loans, grants, sureties and donations.',''),(270,'Articles','Article 231','Article 231. Organisation and Functioning','The law shall regulate the organisation and functioning of the Administrative Court, as well as all other matters related to its powers and jurisdiction.',''),(271,'Articles','Article 232','Article 232. Superior Council of the Administrative Judiciary','The Superior Council of the Administrative Judiciary shall be the body responsible for the management and discipline of the administrative, fiscal and customs judiciary.\nThe law shall regulate the organisation, composition and functioning of the Superior Council of the Administrative Judiciary.',''),(272,'Articles','Article 233','Article 233. Incompatibility','Administrative Court judges in office may not undertake any other public or private activity, except for teaching, legal research or other activities of scientific, literary, artistic and technical dissemination or publication, with prior authorization from the Superior Council of the Administrative Judiciary.',''),(273,'Structure','TITLE X. PUBLIC PROSECUTION SERVICE','TITLE X. PUBLIC PROSECUTION SERVICE','',''),(274,'Articles','Article 234','Article 234. Definition','The Public Prosecution Service shall constitute a hierarchically organized magistracy, which is subordinate to the Attorney General of the Republic.\nIn the exercise of their functions, the judicial officers and agents of the Public Prosecution Service shall be subject to the criteria of legality, objectivity, impartiality and exclusive obedience to the directives and orders prescribed by law.\nThe Public Prosecution Service shall enjoy its own statute and autonomy, within the terms of the law.',''),(275,'Articles','Article 235','Article 235. Nature','The Public Prosecution Service shall comprise a magistracy, the Office of the Attorney General of the Republic and subordinate offices.',''),(276,'Articles','Article 236','Article 236. Functions','The Public Prosecution Service shall represent the State and defend such interests as the law may determine, and it shall control the legality and duration of detentions, shall conduct the institution of criminal proceedings, shall exercise penal authority, and shall ensure the legal defence of minors and absent or incapacitated persons.',''),(277,'Articles','Article 237','Article 237. Office of Attorney General of the Republic','The Office of the Attorney General shall be the highest office of the Public Prosecution Service, and its organisation, composition and powers shall be defined by law.\nThe Attorney General of the Republic, assisted by the Deputy Attorney General of the Republic, shall head the Office of the Attorney General.',''),(278,'Articles','Article 238','Article 238. Superior Council of the Public Prosecution Service','The Office of the Attorney General of the Republic shall include the Superior Council of the Public Prosecution Service, which shall include members elected by the Assembly of the Republic, and members elected by the judicial officers of the Public Prosecution Service from among their number.\nThe Superior Council of the Public Prosecution Service shall be the body responsible for the management and discipline of the Public Prosecution Service.\nThe law shall regulate the organisation, composition and functioning of the Superior Council of the Public Prosecution Service.',''),(279,'Articles','Article 239','Article 239. Attorney General and Deputy Attorney General of the Republic','The Attorney General and the Deputy Attorney General of the Republic shall be appointed by the President of the Republic for a period of five years, from among persons who shall hold degrees in law and shall have at least ten years of professional experience in the judiciary or practice at the bar or in teaching law, and their terms of office may not be terminated otherwise than by:\nresignation;\nexoneration;\ndismissal;\ncompulsory retirement consequent to disciplinary or criminal proceedings;\nacceptance of a position or office which is incompatible with the exercise of his functions.\nThe Attorney General of the Republic shall be accountable to the Head of State.\nThe Attorney General of the Republic shall report annually to the Assembly of the Republic.',''),(280,'Articles','Article 240','Article 240. Deputy Attorneys General','The Deputy Attorneys General shall represent the Public Prosecution Service before the divisions of the Supreme Court and the Administrative Court, and their office shall be the highest office in the magistracy of the Public Prosecution Service.\nDeputy Attorneys General shall be nominated by the President of the Republic on the recommendation of the Superior Council of the Public Prosecution Service, on the basis of their curricula, after a public tender open to national citizens of reputed merit, who shall hold degrees in law and be in full possession of their civil and political rights and who, at the time of the tender, shall be of at least thirty-five years of age and shall have at least ten years of experience in the legal profession or in teaching law.',''),(281,'Structure','TITLE XI. CONSTITUTIONAL COUNCIL','TITLE XI. CONSTITUTIONAL COUNCIL','',''),(282,'Articles','Article 241','Article 241. Definition','The Constitutional Council is a sovereign public office with special jurisdiction to administer justice in matters of a legal-constitutional nature.\nThe law shall determine the organisation, the functioning, the procedures for scrutiny and control of constitutionality and of the legality of normative acts, and all other powers of the Constitutional Council.',''),(283,'Articles','Article 242','Article 242. Composition','The Constitutional Council shall consist of seven judges of appeal, appointed in the following manner:\none judge of appeal, who shall be the President of the Constitutional Council, appointed by the President of the Republic;\nfive judges of appeal appointed by the Assembly of the Republic according to principles of proportional representation;\none judge of appeal appointed by the Superior Council of the Judiciary.\nJudges of the Constitutional Council shall be appointed for renewable terms of five years and they shall enjoy a guarantee of independence, security of tenure, impartiality and unaccountability.\nAt the time of their appointment, Judges of the Constitutional Council shall be of at least thirty-five years of age and shall have at least ten years of professional experience in the judiciary or in practice at the bar or in teaching law.',''),(284,'Articles','Article 243','Article 243. Incompatibility','Judges of the Constitutional Council in office may not undertake any other public or private activity, except for teaching, legal research, or other activities of scientific, literary, artistic and technical dissemination or publication, with prior authorisation from the relevant body.',''),(285,'Articles','Article 244','Article 244. Powers','The Constitutional Council shall have power to:\nevaluate and declare the unconstitutionality of laws and the illegality of normative acts of State offices;\nsettle conflicts of jurisdiction between the sovereign public offices;\nmake prior evaluations of the constitutionality of referenda.\nThe Constitutional Council shall also:\nverify the legal prerequisites required of candidates for the office of President of the Republic;\npronounce upon the permanent incapacity of the President of the Republic;\nverify the death and the divestiture of the President of the Republic;\nevaluate electoral complaints and appeals in the last instance, and validate and proclaim electoral results, in the terms of the law;\ndecide, in the last instance, on the legality of the establishment of political parties and coalitions, as well as evaluate the legality of their names, acronyms and symbols, and order their dissipation in the terms of the Constitution and the laws;\nadjudicate actions contesting elections and the deliberations of political parties, as well as the legality of their names, acronyms and symbols;\nadjudicate actions concerning disputes about the terms of office of deputies;\nadjudicate actions concerning incompatibilities established in the Constitution and in the law.\nThe Constitutional Council shall exercise such other powers as may be assigned to it in terms of the law.',''),(286,'Articles','Article 245','Article 245. Request for Evaluation of Unconstitutionality','The Constitutional Council shall with, general binding force, evaluate and pronounce upon the unconstitutionality of laws and the illegality of other normative acts of State offices, at any time during which they are in force.\nThe following may request the Constitutional Council to pronounce upon the unconstitutionality of laws, or on the illegality of normative acts of State offices:\nthe President of the Republic;\nthe President of the Assembly of the Republic;\nat least one third of the deputies of the Assembly of the Republic;\nthe Prime Minister;\nthe Attorney General of the Republic;\nthe Ombudsman;\ntwo thousand citizens.\nThe law shall establish rules on the admission of actions for the evaluation of unconstitutionality.',''),(287,'Articles','Article 246','Article 246. Anticipatory Finding of Constitutionality','The President of the Republic may request the Constitutional Council to carry out an anticipatory evaluation of the constitutionality of any legal instrument sent to him for enactment.\nAnticipatory evaluation of constitutionality shall be requested within the time limit established in article 163 (2).\nWhen an evaluation of constitutionality has been requested, the time limit for enactment shall be interrupted.\nIf the Constitutional Council finds that there is no unconstitutionality, the new time limit for enactment shall run from the date upon which the President of the Republic is informed of the decision of the Constitutional Council.\nIf the Constitutional Council makes a finding of unconstitutionality, the President of the Republic shall veto the bill and return it to the Assembly of the Republic.',''),(288,'Articles','Article 247','Article 247. Appeals','Supreme Court decisions harmonising questions of law and other decisions made on grounds of unconstitutionality must be referred to the Constitutional Council in the following cases:\nin the event of a refusal to apply any rule on grounds of its unconstitutionality;\nwhen the Attorney General of the Republic or the Public Prosecution Service requests an abstract evaluation of the constitutionality or legality of a rule whose application has been refused, on grounds of unconstitutionality or illegality, by judicial decision from which there is no appeal.\nThe law shall regulate the rules on admissibility of appeals contemplated in this provision.',''),(289,'Articles','Article 248','Article 248. Judgements Binding and Unappealable','Judgements of the Constitutional Council shall be binding on all citizens, institutions and other legal persons, they shall not be subject to appeal and they shall prevail over other decisions.\nA person who fails to comply with the judgements referred to in this article shall be guilty of the criminal offence of contempt, unless a more serious crime applies.\nThe decisions of the Constitutional Council shall be published in the Boletim da República.',''),(290,'Structure','TITLE XII. PUBLIC ADMINISTRATION, POLICE, OMBUDSMA','TITLE XII. PUBLIC ADMINISTRATION, POLICE, OMBUDSMAN AND LOCAL STATE BODIES','',''),(291,'Structure','CHAPTER I. PUBLIC ADMINISTRATION','CHAPTER I. PUBLIC ADMINISTRATION','',''),(292,'Articles','Article 249','Article 249. Fundamental Principles','The Public Administration shall serve the public interests and, in the discharge of its functions, shall respect the fundamental rights and freedoms of citizens.\nThe offices and agents of the Public Administration shall owe obedience to the Constitution and the law, and shall act with respect for the principles of equality, of impartiality, of ethics and of justice.',''),(293,'Articles','Article 250','Article 250. Structure','The Public Administration shall be structured on the basis of the principle of decentralisation and de-concentration, thereby encouraging the modernisation and efficiency of its services, without prejudice to unified action and the directive powers of Government.\nThe Public Administration shall promote the simplification of administrative procedures, and shall make public services more accessible to citizens.',''),(294,'Articles','Article 251','Article 251. Access and Statute of Officers','Access to public office shall not be obstructed on grounds of colour, race, sex, religion, ethnic or social origin, or party-political preference, and shall adhere strictly to the criteria of the merit and ability of applicants.\nThe law shall regulate the statute of officers and other agents of the State, as well as the incompatibilities and the guarantees of impartiality in the exercise of public offices.',''),(295,'Articles','Article 252','Article 252. Hierarchy','In the exercise of their functions, officers and other agents of the State shall owe obedience to their hierarchical superiors in terms of the law.\nThe duty of obedience shall cease whenever to discharge it would involve the commission of a crime.',''),(296,'Articles','Article 253','Article 253. Rights and Guarantees of Citizens','Citizens shall have the right to receive information from the competent Public Administration services, whenever they request it, on the progress of processes in which they have a direct interest, in terms of the law.\nInterested parties shall be notified of administrative acts within the terms and the time limits established by law, and reasons for these acts shall be given whenever they affect the rights or interests of legally entitled citizens.\nInterested citizens shall be guaranteed the right to judicial appeal against the illegality of administrative acts that endanger their rights.',''),(297,'Structure','CHAPTER II. POLICE','CHAPTER II. POLICE','',''),(298,'Articles','Article 254','Article 254. Definition','The function of the Police, in collaboration with other State institutions, shall be to guarantee law and order, to safeguard the security of persons and property, to keep public peace and to ensure respect for the democratic rule of law and the strict observance of the fundamental rights and freedoms of citizens.\nThe Police shall not adhere to any particular party.\nIn the exercise of its functions, the Police shall owe obedience to the law and shall serve citizens and public and private institutions with impartiality and independence.',''),(299,'Articles','Article 255','Article 255. Command and Organisation','The Police of the Republic of Mozambique shall be headed by a Commander-General.\nThe law shall establish the general organisation of the Police and shall determine its branches, its functions, its structure and the rules regarding admission into the Police.',''),(300,'Structure','CHAPTER III. OMBUDSMAN','CHAPTER III. OMBUDSMAN','',''),(301,'Articles','Article 256','Article 256. Definition','The Ombudsman is an office established to guarantee the rights of citizens and to uphold legality and justice in the actions of the Public Administration.',''),(302,'Articles','Article 257','Article 257. Election','The Ombudsman shall be elected by a two-thirds majority of the deputies of the Assembly of the Republic, for a term which shall be determined by law.',''),(303,'Articles','Article 258','Article 258. Independence','The Ombudsman shall be independent and impartial in the exercise of his functions and he shall owe obedience only to the Constitution and the laws.\nThe Ombudsman shall provide report annually on his activity to the Assembly of the Republic.',''),(304,'Articles','Article 259','Article 259. Powers','The Ombudsman shall investigate the cases submitted to him. He shall not have power to make decisions about the cases, but shall submit recommendations to the appropriate offices to correct or prevent illegalities or injustices.\nIf the investigations of the Ombudsman lead to the conclusion that the Public Administration has committed serious mistakes, irregularities or violations, he shall inform the Assembly of the Republic, the Attorney General of the Republic and the central or local authority, with recommendations for pertinent measures.',''),(305,'Articles','Article 260','Article 260. Duty to Collaborate','The offices and agents of the Public Administration shall be under a duty to collaborate with the Ombudsman in the exercise of his functions, should he so request.',''),(306,'Articles','Article 261','Article 261. Statute, Procedures and Organisation','The law shall determine all other aspects pertaining to the statute, the procedures, and the organisational structure supporting the Ombudsman.',''),(307,'Structure','CHAPTER IV. LOCAL STATE BODIES','CHAPTER IV. LOCAL STATE BODIES','',''),(308,'Articles','Article 262','Article 262. Definition','The function of local State bodies shall be to represent the State at local level, in the administration and development of their respective territories, and they shall contribute to national integration and unity.',''),(309,'Articles','Article 263','Article 263. Organisational Principles','The organisation and operation of local State bodies shall adhere to the principles of decentralisation and de-concentration, without prejudice to unified action and the directive powers of Government.\nIn their operation, local State bodies shall promote the use of available resources, ensure the active participation of citizens and encourage local initiative in solving problems of their communities.\nIn their actions, local State bodies shall respect the attributes, powers and autonomy of local authorities.\nSo that it may exercise its particular powers, the State shall ensure that it is represented in the territorial constituency of every local authority.\nThe law shall establish institutional mechanisms for liaison with local communities, and it may delegate to local communities certain functions that are within the powers of the State.',''),(310,'Articles','Article 264','Article 264. Functions','Local State bodies shall, within their respective territories, and without prejudice to the autonomy of local authorities, ensure that economic, cultural and social programmes and tasks of local and national interest are implemented, in accordance with the Constitution and with the decisions of the Assembly of the Republic, the Council of Ministers, and higher ranking State offices.\nThe organisation, functioning and powers of the local State bodies shall be regulated by law.',''),(311,'Structure','TITLE XIII. NATIONAL DEFENCE AND NATIONAL DEFENCE ','TITLE XIII. NATIONAL DEFENCE AND NATIONAL DEFENCE AND SECURITY COUNCIL','',''),(312,'Structure','CHAPTER I. NATIONAL DEFENCE','CHAPTER I. NATIONAL DEFENCE','',''),(313,'Articles','Article 265','Article 265. Fundamental Principles','The State’s national defence and security policy shall seek to defend national independence, to preserve the sovereignty and the integrity of the country, and to guarantee the normal functioning of institutions and the security of citizens against any armed aggression.',''),(314,'Articles','Article 266','Article 266. Defence Force and Security Service','The defence force and the security service shall be subordinate to national defence and security policy and shall owe allegiance to the Constitution and to the nation.\nThe oath taken by members of the State’s defence force and security service shall establish the duty to respect the Constitution, to protect institutions and to serve the people.\nThe State’s defence force and security service shall not adhere to any party and they shall abstain from taking positions or taking part in actions that could threaten their internal cohesion and national unity.\nThe State’s defence force and security service shall owe special obedience to the President of the Republic, in his capacity as Commander-in-Chief.',''),(315,'Articles','Article 267','Article 267. Defence of the Motherland, Military Service and Civic Service','It shall be the sacred duty and the honour of all Mozambican citizens to participate in the defence of independence, of sovereignty and of territorial integrity.\nMilitary service shall be rendered in terms of the law within units of the Mozambique Armed Defence Forces.\nThe law shall establish a civic service to substitute or complement military service for all citizens who are not subject to military duties.\nExemptions from military service shall be established by law.',''),(316,'Structure','CHAPTER II. NATIONAL DEFENCE AND SECURITY COUNCIL','CHAPTER II. NATIONAL DEFENCE AND SECURITY COUNCIL','',''),(317,'Articles','Article 268','Article 268. Definition and Composition','The National Defence and Security Council shall be the State consultative body for matters pertaining to national sovereignty, territorial integrity, the defence of democratically established authority, and security.\nThe National Defence and Security Council shall be presided over by the President of the Republic and the law shall determine its composition, which shall include two members appointed by the President of the Republic and five members appointed by the Assembly of the Republic.',''),(318,'Articles','Article 269','Article 269. Powers','The National Defence and Security shall have the following powers, in particular:\nto pronounce upon a state of war before such is declared;\nto pronounce upon the suspension of constitutional guarantees and the declaration of a state of siege or of a state of emergency;\nto issue an opinion on the criteria and conditions governing the use of total or partial protection zones for the purposes of defence and security of the national territory;\nto analyse and monitor the initiatives of other State offices aimed at guaranteeing the consolidation of national independence, the strengthening of democratic political power, and the maintaining of law and order;\nto pronounce upon overseas peace missions.',''),(319,'Articles','Article 270','Article 270. Organisation and Functioning','The organisation and functioning or the National Defence and Security Council shall be established by law.',''),(320,'Structure','TITLE XIV. LOCAL ADMINISTRATION','TITLE XIV. LOCAL ADMINISTRATION','',''),(321,'Articles','Article 271','Article 271. Objectives','The objective of local administration shall be to organise the participation of citizens in solving the particular problems of their community, to promote local development, and to promote the deepening and the consolidation of democracy, within the framework of unity of the Mozambican State.\nLocal administration shall rest on the initiative and the capacity of the people and shall act in strict collaboration with organisations in which the citizens participate.',''),(322,'Articles','Article 272','Article 272. Local Authorities','Local administration shall consist of local authorities.\nLocal authorities shall be bodies corporate governed by public law, endowed with their own representative bodies, and their purpose shall be to pursue the interests of the local population, without prejudice to national interests and to the role of the State.',''),(323,'Articles','Article 273','Article 273. Categories of Local Authorities','Local authorities shall be municipalities and settlements.\nThe municipalities shall correspond to the territorial constituency of towns and cities.\nThe settlements shall correspond to the territorial constituency of administrative posts.\nThe law may establish other categories of local authorities, which may be either greater or smaller than the territorial constituencies of municipalities or settlements.',''),(324,'Articles','Article 274','Article 274. Creation and Dissipation of Local Authorities','The creation and dissipation of local authorities shall be regulated by law, and changes to the area of a particular local authority shall be preceded by consultation with its bodies.',''),(325,'Articles','Article 275','Article 275. Executive and Decision Making Bodies','The local authorities shall possess and assembly endowed with decision- making powers, and an executive body, which shall be accountable to the assembly, in terms of the law.\nThe Assembly shall be elected through universal, direct, equal and periodic suffrage and by secret and personal ballot, by the voters living within the territorial constituency of the local authority, according to the system of proportional representation.\nThe executive body shall be headed by a President, elected through universal, direct, equal and periodic suffrage and by secret and personal ballot, by the voters living with the respective territorial constituency.\nCandidates for election to offices of the local authorities may be proposed by political parties, either individually or as coalitions, or by groups of voters, within the terms of the law.\nThe organisation, the composition and the functioning of the executive bodies shall be defined by law.',''),(326,'Articles','Article 276','Article 276. Local Property and Revenue','Local authorities shall have their own property and revenue.\nThe law shall determine the property of local authorities and shall establish a local revenue system that guarantees the fair distribution of public resources and ensures that necessary adjustments are made to correct the imbalances between them, subject to the higher interests of the State.\nThe law shall define the forms of technical and human support given by the State to the local authorities, without prejudice to their autonomy.',''),(327,'Articles','Article 277','Article 277. Administrative Supervision','The local authorities shall be subject to the administrative supervision of the State.\nAdministrative supervision over local authorities shall consist of verifying the legality of administrative acts of local authorities, within the terms of the law.\nSupervisory power may also be exercised with respect to the merit of administrative acts, but only in cases and within the terms expressly established by law.\nLocal authority bodies may only be dissolved, even when pursuant to direct elections, as a result of serious legal acts or omissions, as provided for by and in accordance with the terms of the law.',''),(328,'Articles','Article 278','Article 278. Regulatory Powers','Local authorities shall have their own regulatory powers, within the limits of the Constitution and of the laws and regulations issued by authorities with supervisory power over them.',''),(329,'Articles','Article 279','Article 279. Staff of Local Authorities','Local authorities shall have their own staff, in accordance with the law.\nThe regime governing officers and agents of the State shall be applicable to officers and agents of local administration.',''),(330,'Articles','Article 280','Article 280. Organisation','The law shall guarantee the forms of organisation that the local authorities may adopt to further common interests.',''),(331,'Articles','Article 281','Article 281. Term of Office','The law shall govern the resignation and loss of office of elected members of local authority bodies.',''),(332,'Structure','TITLE XV. CONSTITUTIONAL GUARANTEES','TITLE XV. CONSTITUTIONAL GUARANTEES','',''),(333,'Structure','CHAPTER I. STATES OF SIEGE AND OF EMERGENCY','CHAPTER I. STATES OF SIEGE AND OF EMERGENCY','',''),(334,'Articles','Article 282','Article 282. States of Siege or of Emergency','A state of siege or of emergency may be declared, in the whole or in part of the territory, only in cases of actual or imminent aggression, cases of disruption of or serious threat to the constitutional order, or in the event of a public disaster.\nThe declaration of a state of siege or of emergency shall be reasoned and shall specify which freedoms and guarantees have been suspended or restricted.',''),(335,'Articles','Article 283','Article 283. Choice of Declaration','When the circumstances giving rise to the declaration are of a less serious nature, a declaration of emergency shall be chosen, provided that the principle of proportionality shall be respected in all cases, and the duration and extent of the measures used shall be limited to what is strictly necessary for the prompt restoration of constitutional normality.',''),(336,'Articles','Article 284','Article 284. Duration','The duration of a state of siege or of emergency shall not exceed thirty days, which may be extended for the same period up to three times, if the reasons for the declaration persist.',''),(337,'Articles','Article 285','Article 285. The Declaration Process','Having declared a state of siege or of emergency, the President of the Republic shall, within twenty-four hours, submit the declaration together with the reasons for it to the Assembly of the Republic for the purposes of ratification.\nIf the Assembly of the Republic is not in session, an extraordinary session shall be convened and should meet within a maximum period of five days.\nThe Assembly of the Republic shall evaluate and decide on the declaration within a maximum period of forty eight hours, and may remain in session while the state of siege or of emergency is in place.',''),(338,'Articles','Article 286','Article 286. Limits of the Declaration','The declaration of a state of siege or a state of emergency shall in no event restrict or suspend the right to life, the right to personal integrity, the right to civil capacity and to citizenship, the non-retroactivity of criminal law, the right of accused persons to a defence, and freedom of religion.',''),(339,'Articles','Article 287','Article 287. Restrictions on Individual Freedoms','Under a state of siege or a state of emergency, the following measures restricting personal freedoms may be taken:\nobligation to remain in a certain place;\ndetention;\ndetention in buildings not intended for persons accused or convicted of common crimes;\nrestrictions relating to the inviolability of correspondence, the confidentiality of communication, the provision of information and the freedom of the press and of radio and television broadcasting;\nhome search and apprehension;\nsuspension of the freedom of assembly and demonstration;\nrequisitions of goods and services.',''),(340,'Articles','Article 288','Article 288. Detention','Detentions carried out under a state of siege or of emergency shall adhere to the following principles:\na relative or trusted acquaintance of the detainee, indicated by the detainee, shall be notified immediately and informed about the applicable legal rules within a period of five days;\nthe name of the detainee and the legal basis for his detention shall be made public within five days;\nthe detainee shall come before a judge within a maximum of ten days.',''),(341,'Articles','Article 289','Article 289. Functioning of the Sovereign Public Offices','The declaration of a state of siege or a state of emergency must not affect the application of the Constitution in respect of the powers and the functioning of the sovereign public offices, or in respect of the rights and immunities of the respective office holders or members.',''),(342,'Articles','Article 290','Article 290. Termination','Upon the termination of a state of siege or of emergency, the President of the Republic shall address a message to the Assembly of the Republic, giving detailed information about the measures taken under it and a list of the names of all citizens affected.\nThe termination of the state of siege or of emergency shall bring its effects to an end, but this shall not affect responsibility for unlawful acts committed by agents or persons who implemented it.',''),(343,'Structure','CHAPTER II. AMENDING THE CONSTITUTION','CHAPTER II. AMENDING THE CONSTITUTION','',''),(344,'Articles','Article 291','Article 291. Initiative','Proposals to amend the Constitution shall be introduced on the initiative of the President of the Republic or of at least one third of the deputies of the Assembly of the Republic.\nProposed amendments to the Constitution shall be laid before the Assembly of the Republic ninety days before the opening of debate.',''),(345,'Articles','Article 292','Article 292. Restrictions as to Subject Matter','Constitutional amendment laws shall have to respect the following:\nthe independence, the sovereignty and the unity of the State;\nthe republican form of Government;\nthe separation between religious denominations and the State;\nthe fundamental rights, freedoms and guarantees;\nuniversal, direct, secret, personal, equal and periodic suffrage for the appointment of elective sovereign public offices and elective offices of local administration;\npluralism of expression and of political organisation, including political  parties and the right of democratic opposition;\nthe separation and interdependence of the sovereign public offices;\nthe scrutiny of constitutionality;\nthe independence of the judiciary;\nthe autonomy of local authorities;\nthe rights of workers and trade unions;\nthe rules governing nationality, which cannot be amended in such a way as to restrict or remove rights of citizenship.\nAmendments pertaining to the matters listed in the preceding paragraph must, obligatorily, be submitted to a referendum.',''),(346,'Articles','Article 293','Article 293. Restrictions as to Time','The Constitution may only be amended after five years have passed since the last amending legislation entered into force, except when a decision to assume  extraordinary amending powers has been passed by a majority of three quarters  of the deputies in the Assembly of the Republic.',''),(347,'Articles','Article 294','Article 294. Restrictions as to Circumstances','No amendments to the Constitution shall be passed during a state of siege or state of emergency.',''),(348,'Articles','Article 295','Article 295. Voting and Form','Amendments to the Constitution shall be carried by a majority of two thirds of the deputies of the Assembly of the Republic.\nThe constitutional amendments that are approved shall be consolidated into a single amending law.\nThe President of the Republic cannot refuse to enact the amending law.',''),(349,'Articles','Article 296','Article 296. Constitutional Amendments','Amendments to the Constitution shall be inserted into the appropriate place, by making the necessary substitutions, deletions and additions.\nThe Constitution, as amended, shall be published together with the amending law.',''),(350,'Structure','TITLE XVI. SYMBOLS, CURRENCY AND CAPITAL OF THE RE','TITLE XVI. SYMBOLS, CURRENCY AND CAPITAL OF THE REPUBLIC','',''),(351,'Articles','Article 297','Article 297. National Flag','The national flag shall have five colours: red, green, black, gold and white.\nThe significance of these colours shall be as follows:\nred – the centuries of resistance to colonialism, the armed national liberation struggle and defence of sovereignty;\ngreen – the riches of the soil;\nblack – the African continent;\ngold – the riches of the subsoil;\nwhite – the justice of the struggle of the Mozambican people, and peace.\nFrom top to bottom, there shall be green, black and gold horizontal stripes, separated by strips of white. On the left side, there shall be a red triangle, in the centre of which there shall be a star. Above this there shall be a crossed hoe and gun, superimposed on a book.\nThe star shall symbolise the spirit of international solidarity of the Mozambican people.\nThe book, the hoe and the gun shall symbolise study, production and defence.',''),(352,'Articles','Article 298','Article 298. Emblem','The emblem of the Republic of Mozambique shall contain as its central elements a book, a gun and hoe, superimposed on a map of Mozambique, and representing, respectively: education, defence and vigilance, and the peasantry and agricultural production.\nBelow the map the ocean shall be represented.\nIn the centre shall be the rising sun, symbol of the building of a new life.\nEnclosing this shall be a toothed wheel, symbolising the workers and industry.\nSurrounding the toothed wheel there shall be, to the right and left respectively, an ear of maize and a piece of sugar cane, symbolising agricultural wealth.\nAt the top, in the centre, shall be a star, symbolising the spirit of international solidarity of the Mozambican people.\nAt the bottom there shall be a red stripe with the inscription “Republic of Mozambique”.',''),(353,'Articles','Article 299','Article 299. National Anthem','The words and the music of the national anthem shall be established by law, which shall be passed in accordance with article 280 (1).',''),(354,'Articles','Article 300','Article 300. Currency','The national currency shall be the Metical.\nChanges to the currency shall be established by law, which shall be passed in accordance with article 295 (1).',''),(355,'Articles','Article 301','Article 301. Capital','The Capital of the Republic of Mozambique shall be the City of Maputo.',''),(356,'Structure','TITLE XVII. FINAL AND TRANSITORY PROVISIONS','TITLE XVII. FINAL AND TRANSITORY PROVISIONS','',''),(357,'Articles','Article 302','Article 302. Flag and Emblem','Changes to the national flag and the emblem of the Republic of Mozambique shall be established by law, which shall be passed in accordance with article 295 (1) within a period of one year of the date upon which this Constitution enters into force.',''),(358,'Articles','Article 303','Article 303. Constitutional Council','When the Constitution enters into force, the Constitutional Council shall remain in office with its current composition and shall assume the powers established in Title Ten.',''),(359,'Articles','Article 304','Article 304. Provincial Assemblies','The elections to the provincial assemblies, provided for in article 142 of the Constitution, shall be held before the year 2009.',''),(360,'Articles','Article 305','Article 305. Previous Law','Insofar as it is not contrary to the Constitution, previous legislation shall remain in force until it is modified or repealed.',''),(361,'Articles','Article 306','Article 306. Entry into Force','The Constitution shall come into force on the day immediately following the day on which the results of the 2004 General Election are validated and proclaimed.','');
